window.BANQUE_INFINI = {"module":"annee-2/pratique/semestre-1/eaif-3","titre":"EAIF III","sources":[{"t":"Chaînes musculaires — examen et traitement","q":"chaines-musculaires-pratique/quiz.html","f":"chaines-musculaires-pratique/fiche.html"},{"t":"PNF — diagonales de mouvement","q":"pnf-diagonales/quiz.html","f":"pnf-diagonales/fiche.html"},{"t":"PNF — techniques spécifiques","q":"pnf-techniques-specifiques/quiz.html","f":"pnf-techniques-specifiques/fiche.html"},{"t":"Santé au travail — surveillance et intervention","q":"sante-au-travail-pratique/quiz.html","f":"sante-au-travail-pratique/fiche.html"},{"t":"Stabilité de l'épaule — évaluation et thérapie manuelle","q":"stabilite-epaule-pratique/quiz.html","f":"stabilite-epaule-pratique/fiche.html"},{"t":"Stabilité lombaire — évaluation et tests","q":"stabilite-lombaire-evaluation/quiz.html","f":"stabilite-lombaire-evaluation/fiche.html"},{"t":"Stabilité lombaire — chaînes, slings et traitement","q":"stabilite-lombaire-traitement/quiz.html","f":"stabilite-lombaire-traitement/fiche.html"}],"questions":[{"q":"Quel est l'objectif de l'examen en chaînes musculaires ?","o":["Déterminer les tensions internes","Mesurer la force maximale","Évaluer l'endurance cardio-respiratoire","Quantifier la douleur uniquement"],"r":0,"e":"Les signes doivent être clairs et évidents.","s":0},{"q":"Comment conduit-on l'examen en situation aiguë ?","o":["Rapide, traitement local, évaluation complétée plus tard","Minutieux et global d'emblée, avant tout traitement local","Sans traitement, l'évaluation complète passant en premier","Traitement à distance seulement, sans examen local"],"r":0,"e":"On investigue plus en profondeur lors des séances suivantes.","s":0},{"q":"Dans quel ordre se déroule l'examen en situation chronique ?","o":["De la tête aux pieds, de la superficie à la profondeur, du statique au dynamique","Des pieds à la tête, de la profondeur à la superficie, du dynamique au statique","De la tête aux pieds, de la profondeur à la superficie, du dynamique au statique","Des pieds à la tête, de la superficie à la profondeur, du statique au dynamique"],"r":0,"e":"Il est minutieux, précis, global et long.","s":0},{"q":"Que permet de découvrir l'examen statique ?","o":["L'organisation des forces autour de points fixes, et les zones de tension","La zone immobile autour de laquelle le corps articule ses tensions","La force musculaire maximale de chaque chaîne, et ses déséquilibres","La souplesse articulaire de chaque segment, et ses limitations"],"r":0,"e":"L'examen dynamique recherche la zone immobile autour de laquelle le corps articule les tensions.","s":0},{"q":"Que recherche l'examen dynamique ?","o":["La zone immobile autour de laquelle le corps articule ses tensions","L'organisation des forces autour des points fixes, en statique","La longueur réelle et apparente des deux membres inférieurs","Le tonus de repos des muscles de chaque chaîne, couché"],"r":0,"e":"L'examen statique révèle l'organisation des forces autour des points fixes.","s":0},{"q":"Quel élément s'observe en vue postérieure debout ?","o":["Les tendons d'Achille verticaux, les plis fessiers symétriques","L'angle xiphoïdien, l'ouverture du gril costal inférieur","L'horizontalité des mamelons, la hauteur des clavicules","La ligne médiane des incisives et l'occlusion dentaire au repos"],"r":0,"e":"On observe aussi la hauteur des grands trochanters, des crêtes iliaques, des EIPS et des mastoïdes.","s":0},{"q":"Quel élément s'observe en vue antérieure ?","o":["Les rotules convergentes ou divergentes, hautes ou basses","L'alignement occipito-dorso-sacré, l'angle tronc-cuisse, les genoux","Les courbures scoliotiques, la position des scapulas","La hauteur des EIPS, la symétrie des plis fessiers"],"r":0,"e":"On observe aussi l'angle xiphoïdien, l'horizontalité des mamelons et l'occlusion.","s":0},{"q":"Quel intérêt présente l'évaluation posturale en position assise ?","o":["Voir les crêtes iliaques sans l'effet des membres inférieurs","Mesurer la force des fessiers sans l'effet du poids du corps","Évaluer l'arche plantaire sans l'effet de l'appui au sol, pieds nus","Tester le diaphragme sans l'effet des muscles abdominaux"],"r":0,"e":"On y observe aussi la flexion, l'extension et les rotations.","s":0},{"q":"En décubitus dorsal, quel mouvement teste la chaîne d'extension ?","o":["L'élévation des membres inférieurs","L'élévation des membres supérieurs","La flexion cervicale","La rotation du tronc"],"r":0,"e":"L'élévation des membres supérieurs teste la chaîne de flexion.","s":0},{"q":"À quel niveau vertébral passe l'aorte à travers le diaphragme ?","o":["T12","T9","T10","L1"],"r":0,"e":"La veine cave passe en T9 et l'œsophage en T10.","s":0},{"q":"À quel niveau passe la veine cave ?","o":["T9","T10","T12","T8"],"r":0,"e":"Sa pseudo-valve facilite la montée du sang veineux à l'inspiration et la freine à l'expiration.","s":0},{"q":"Pourquoi l'orifice œsophagien est-il essentiellement musculaire ?","o":["Pour éviter la régurgitation","Pour faciliter le retour veineux","Pour ne pas perturber le flux artériel","Pour amortir les chocs"],"r":0,"e":"Il se situe en T10, à gauche.","s":0},{"q":"Pourquoi l'orifice aortique est-il fibreux et non élastique ?","o":["Pour ne pas perturber le flux artériel","Pour éviter la régurgitation","Pour faciliter la montée du sang veineux","Pour permettre l'expansion costale"],"r":0,"e":"Il se situe au niveau de T12.","s":0},{"q":"Comment se comportent les pouces du kiné avec un diaphragme hypertonique ?","o":["Ils montent à l'inspiration, sans redescendre sous le départ à l'expiration","Ils montent et redescendent normalement, au rythme de la respiration","Ils montent à peine, puis redescendent bien sous le point de départ","Ils restent immobiles, à l'inspiration comme à l'expiration, sans aucun mouvement"],"r":0,"e":"Le diaphragme hypertonique fonctionne en inspiration.","s":0},{"q":"Comment se comporte un diaphragme hypotonique ?","o":["En position haute : les pouces montent peu, descendent bien sous le départ","En inspiration : les pouces montent, sans redescendre sous le départ","Normalement : les pouces montent et descendent au rythme respiratoire","Bloqué : les pouces restent immobiles, à l'inspiration comme à l'expiration"],"r":0,"e":"La reprogrammation consiste à inspirer par l'abdomen et expirer en maintenant l'abdomen gonflé. Il fonctionne en expiration.","s":0},{"q":"Quelle reprogrammation propose-t-on pour un diaphragme hypertonique ?","o":["Expirer en rentrant l'abdomen","Inspirer par l'abdomen, expirer en le gardant gonflé","Travailler en apnée, abdomen rentré","Ne rien faire, le diaphragme se régule seul"],"r":0,"e":"Pour l'hypotonique, on inspire par l'abdomen et on expire en maintenant l'abdomen gonflé.","s":0},{"q":"Quelle est l'origine du carré des lombes ?","o":["La crête iliaque et le ligament ilio-lombaire","Les corps et les processus transverses de T12 à L5","La fosse iliaque interne","Le petit trochanter du fémur"],"r":0,"e":"Il s'insère sur la 12ᵉ côte et les processus transverses de L1 à L5.","s":0},{"q":"Où se termine le psoas-iliaque ?","o":["Sur le petit trochanter du fémur","Sur la crête iliaque, en arrière","Sur la 12ᵉ côte, au bord inférieur","Sur le grand trochanter du fémur"],"r":0,"e":"Le psoas naît de T12 à L5 et fusionne avec l'iliaque, issu de la fosse iliaque.","s":0},{"q":"Quel principe résume l'approche « relâcher / ne pas étirer » ?","o":["Libérer l'hyper-programmation pour que la tension disparaisse","Étirer au maximum chaque muscle pour allonger toute la chaîne","Renforcer la chaîne opposée avant de chercher à relâcher celle-ci","Immobiliser la zone pour que la tension disparaisse seule"],"r":0,"e":"On associe l'analytique au sein de la globalité et la libération des points fixes.","s":0},{"q":"Pourquoi la respiration est-elle centrale dans le travail des chaînes ?","o":["Toutes les chaînes musculaires se croisent au diaphragme","Elle permet de mesurer l'effort fourni pendant la posture","Elle remplace les postures quand le patient est fatigué","Elle permet l'apnée, qui verrouille la posture pendant le travail"],"r":0,"e":"Il ne faut jamais travailler en apnée et il faut relâcher pendant l'expiration.","s":0},{"q":"Quelle technique s'applique à une chaîne hyper-programmée ?","o":["Les techniques d'inhibition","Les techniques de relâchement","Le renforcement excentrique","La mobilisation passive rapide"],"r":0,"e":"Les techniques de relâchement s'adressent à la chaîne contracturée.","s":0},{"q":"Quel est le 1ᵉʳ tracé de la moitié inférieure de la chaîne posturale ?","o":["Bilatéral, contournant le sacrum en dessinant un losange","De l'EIPS au grand trochanter, de chaque côté du bassin","Du sacrum à T12, le long des processus épineux","Sur la ligne blanche, de l'ombilic au pubis"],"r":0,"e":"La ligne blanche appartient à la chaîne de flexion.","s":0},{"q":"Quel tracé est circulaire autour du processus épineux de C7 ?","o":["Le 4ᵉ tracé de la moitié supérieure","Le 1ᵉʳ tracé de la moitié supérieure","Le 7ᵉ tracé de la moitié supérieure, circulaire","Le 5ᵉ tracé de la moitié supérieure"],"r":0,"e":"Le 5ᵉ va d'une apophyse acromiale à l'autre en passant sous l'épine de la scapula.","s":0},{"q":"Quel est le 7ᵉ tracé de la moitié supérieure ?","o":["Sur les lignes courbes occipitales, d'une mastoïde à l'autre","De T12 à l'acromion, le long du bord externe du grand dorsal","Autour de C7, en cercle centré sur le processus épineux","Sur les bords costaux inférieurs, de la xiphoïde aux flancs"],"r":0,"e":"Le 6ᵉ va de l'acromion à l'occiput par le bord supérieur du trapèze.","s":0},{"q":"Quel tracé appartient à la chaîne de flexion (moitié inférieure) ?","o":["Sur la ligne blanche, de haut en bas","Autour du sacrum, en forme de losange","Du sacrum à T12, de bas en haut","De T12 à l'occiput, le long du rachis"],"r":0,"e":"On y trouve aussi le bord externe des droits de l'abdomen, les arcades crurales et les bords costaux inférieurs.","s":0},{"q":"Quel est le rythme du pompage des chaînes d'extension et de flexion ?","o":["3 s de tension, 3 s de relâchement, sans revenir au départ","Tension constante, maximale à l'inspiration, sans relâchement","5 s de tension, 5 s de relâchement, avec retour au départ","10 s de maintien, 10 s de relâchement, avec retour au départ"],"r":0,"e":"Le pompage de la chaîne posturale se fait à tension constante, avec un maximum pendant l'expiration.","s":0},{"q":"Quelles consignes accompagnent la posture globale pendant l'expiration ?","o":["Pousser les talons vers le haut et « rentrer » le ventre","Bloquer la respiration et relâcher les orteils en griffe","Pousser les épaules en avant et rentrer le menton","Fléchir les genoux et laisser le ventre se gonfler"],"r":0,"e":"La position de départ comprend pieds joints et parallèles, orteils en griffe et flexion dorsale maximale.","s":0},{"q":"Quel est le test de positionnement de la 1ʳᵉ côte ?","o":["L'obstruction de la fosse sous-claviculaire","La douleur à la palpation du sternum","La limitation de la rotation cervicale","L'asymétrie des mastoïdes"],"r":0,"e":"Le test de mobilité montre une descente bloquée plus tôt que la normale à l'expiration.","s":0},{"q":"Comment posture-t-on le petit pectoral ?","o":["Bras le long du corps, mains en supination, bâton sous les fessiers","Bras à 130° d'abduction et en rotation externe, coude tendu, paume au mur","Bras à la verticale, coude tendu, poing fermé","Debout, main à plat au mur, doigts vers le bas, coude tendu"],"r":0,"e":"On stabilise l'apophyse coracoïde et on exerce une pression sur la grille costale à l'expiration.","s":0},{"q":"Quel morphotype correspond à la chaîne d'extension du membre inférieur ?","o":["Antéversion du bassin, recurvatum des genoux, arche plantaire peu marquée","Rétroversion du bassin, flexum des genoux, arche plantaire très creuse","Bassin neutre, varus des genoux, supination des pieds","Bassin neutre, valgus des genoux, pronation des pieds"],"r":0,"e":"Le varus et la supination caractérisent la chaîne d'ouverture, le valgus et la pronation la chaîne de fermeture.","s":0},{"q":"En situation aiguë, l'examen en chaînes musculaires est :","o":["Minutieux et global, le traitement venant après le bilan complet","Rapide, avec un traitement local et un bilan complété plus tard","Impossible, le bilan étant reporté à la fin de la phase aiguë","Identique au chronique, de la tête aux pieds et du statique au dynamique"],"r":1,"e":"En situation chronique, il devient minutieux, précis, global et long : de la tête aux pieds, de la superficie à la profondeur, du statique au dynamique.","s":0},{"q":"L'examen statique permet de découvrir :","o":["La zone immobile autour de laquelle le corps articule ses tensions","L'organisation des forces autour de points fixes, et les zones de tension","La force musculaire maximale de chaque chaîne, et ses déséquilibres","Les amplitudes articulaires de chaque segment, et leurs limitations"],"r":1,"e":"L'examen dynamique recherche, lui, la zone immobile autour de laquelle le corps organise ses tensions.","s":0},{"q":"L'évaluation en chaînes musculaires se réalise :","o":["Debout uniquement, en statique, avec photos de face et de profil","Debout, assis et couché, en statique puis en dynamique, avec body chart","Couché uniquement, en dynamique, avec report sur un schéma corporel","En mouvement uniquement, à la marche, avec enregistrement vidéo"],"r":1,"e":"Le body chart permet de consigner les observations de façon synthétique et de suivre leur évolution d'une séance à l'autre.","s":0},{"q":"En vue postérieure debout, on observe notamment :","o":["L'angle xiphoïdien et l'horizontalité des deux mamelons","La verticalité des tendons d'Achille et la symétrie des plis fessiers","L'occlusion dentaire et la ligne médiane des incisives","Le recurvatum du genou et l'angle formé par le tronc et la cuisse"],"r":1,"e":"S'y ajoutent la hauteur des grands trochanters et des crêtes iliaques, les courbures scoliotiques, les scapulas et la hauteur des mastoïdes. On regarde aussi la hauteur des EIPS.","s":0},{"q":"En vue latérale, on évalue notamment :","o":["La symétrie des plis fessiers, la hauteur des EIPS et des crêtes","Le genou, l'angle tronc-cuisse et l'alignement occipito-dorso-sacré","L'horizontalité des mamelons, l'angle xiphoïdien et l'occlusion","La convergence des rotules, l'angle pieds-jambes-cuisses et les EIAS"],"r":1,"e":"S'y ajoutent l'analyse du pied, les courbures postérieures et antérieures, les membres supérieurs, la tête et la mandibule. Au genou : recurvatum ou flexum.","s":0},{"q":"En vue antérieure, on recherche notamment :","o":["Les rotules convergentes ou divergentes et hautes ou basses","La verticalité des tendons d'Achille et des talons","L'alignement occipito-dorso-sacré et la cyphose dorsale","La hauteur des mastoïdes et des grands trochanters"],"r":0,"e":"S'y ajoutent l'angle pieds-jambes-cuisses, les EIAS, la paroi abdominale, l'angle xiphoïdien, l'horizontalité des mamelons et l'occlusion dentaire.","s":0},{"q":"L'évaluation posturale en position assise présente l'intérêt :","o":["D'être plus rapide que l'évaluation debout","De s'affranchir de l'influence des membres inférieurs","D'éviter la fatigue du patient pendant tout l'examen","De mieux voir le rachis cervical et les épaules"],"r":1,"e":"On y observe la hauteur des crêtes iliaques ainsi que la flexion, l'extension et les rotations.","s":0},{"q":"En décubitus dorsal, la chaîne d'extension se teste par :","o":["L'élévation des membres inférieurs","L'élévation des membres supérieurs","La flexion du tronc","La rotation de la tête"],"r":0,"e":"L'élévation des membres supérieurs teste, elle, la chaîne de flexion.","s":0},{"q":"Le cours pose comme règle, toutes les chaînes se croisant au diaphragme :","o":["De travailler en apnée pour verrouiller le diaphragme","De ne jamais travailler en apnée et de relâcher à l'expiration","De bloquer l'inspiration pour mieux tenir la posture","De respirer rapidement pour oxygéner les muscles en tension"],"r":1,"e":"L'apnée verrouille le diaphragme et empêche précisément le relâchement que l'on cherche à obtenir sur les chaînes.","s":0},{"q":"Le diaphragme hypertonique se reconnaît au fait qu'il :","o":["Fonctionne en position haute, en expiration","Fonctionne en inspiration","Ne bouge pas, ni en inspiration ni en expiration","Fonctionne normalement, aux deux temps"],"r":1,"e":"Les trois états décrits sont normotonique, hypertonique et hypotonique — ce dernier fonctionnant en position haute, en expiration.","s":0},{"q":"Chez un patient normotonique, les pouces du kinésithérapeute :","o":["Restent immobiles pendant tout le cycle respiratoire","Montent et descendent au rythme de la respiration","Ne montent qu'à l'inspiration, sans jamais redescendre","Ne descendent qu'à l'expiration, sans jamais remonter"],"r":1,"e":"Cette palpation simple permet de classer le comportement diaphragmatique avant toute intervention sur les chaînes.","s":0},{"q":"À l'inspiration, le péricarde est :","o":["Relâché, puis tendu à l'expiration","Tiré vers le bas et les côtés","Comprimé vers le haut et l'avant","Immobile, quel que soit le temps respiratoire"],"r":1,"e":"Il est relâché à l'expiration. Cette alternance tension-relâchement du diaphragme facilite la vascularisation.","s":0},{"q":"Le pompage des chaînes d'extension et de flexion se réalise selon le rythme :","o":["1 s de tension, 1 s de relâchement, en revenant au départ","3 s de tension, 3 s de relâchement, sans revenir au départ","10 s de tension, 10 s de relâchement, en revenant au départ","Tension continue de 30 s, sans relâchement intermédiaire"],"r":1,"e":"Le fait de ne pas revenir au point de départ permet de gagner progressivement en amplitude d'une répétition à l'autre.","s":0},{"q":"L'objectif de l'examen en chaînes musculaires est :","o":["De mesurer la force de chaque chaîne, sur une échelle de 0 à 5","De déterminer les tensions internes, sur des signes clairs et évidents","D'établir un diagnostic médical, sur des signes radiologiques et biologiques","De quantifier les amplitudes, sur des mesures au goniomètre"],"r":1,"e":"L'exigence de clarté des signes évite de bâtir un raisonnement sur des observations douteuses, risque réel dans une évaluation aussi globale.","s":0},{"q":"En position couchée, l'observation se fait :","o":["Uniquement de face, au pied de la table","À partir de la tête et des pieds, puis de profil","Uniquement de profil, pour voir les courbures","En mouvement seulement, pendant les retournements"],"r":1,"e":"De la tête et des pieds, on observe la position de la tête, la rotation des membres, la hauteur des épaules et la position des mains et des pieds. De profil, on observe les lordoses et les cyphoses.","s":0},{"q":"L'évaluation dynamique debout et assis vérifie :","o":["Les lignes, les zones planes, les ruptures et les restrictions","La force musculaire des chaînes, cotée de 0 à 5 au testing manuel","Les réflexes ostéotendineux des quatre membres","La sensibilité superficielle et profonde des membres"],"r":0,"e":"Les zones de rupture signalent les endroits où la continuité de la chaîne se brise, souvent là où se concentrent les contraintes. Les lignes sont antérieure et postérieure.","s":0},{"q":"Le diaphragme hypotonique se caractérise par un fonctionnement :","o":["En inspiration, en position basse","En position haute, en expiration","Normal, aux deux temps du cycle","Absent, sans aucun mouvement"],"r":1,"e":"L'hypertonique fonctionne au contraire en inspiration. Identifier l'état diaphragmatique oriente directement la technique employée.","s":0},{"q":"L'ordre de progression de l'examen chronique est :","o":["Des pieds à la tête, du profond au superficiel, du statique au dynamique","De la tête aux pieds, de la superficie à la profondeur, du statique au dynamique","De la tête aux pieds, du profond au superficiel, du dynamique au statique","Des pieds à la tête, de la superficie à la profondeur, du dynamique au statique"],"r":1,"e":"Cette systématisation garantit qu'aucune région n'est omise dans un examen qui se veut global et long.","s":0},{"q":"L'orifice œsophagien du diaphragme se situe :","o":["À T9, à droite","À T10, à gauche","À T12, au centre","À T8"],"r":1,"e":"La veine cave passe à T9 et l'aorte à T12. Ces trois niveaux sont à connaître précisément pour l'examen.","s":0},{"q":"L'examen dynamique en décubitus dorsal explore les chaînes par :","o":["L'élévation des membres inférieurs, puis celle des membres supérieurs","La rotation du tronc seule, d'un côté puis de l'autre","Des tests de force, chaîne par chaîne, contre une résistance manuelle maximale","Des mobilisations passives, segment par segment"],"r":0,"e":"Ces deux manœuvres simples permettent d'apprécier globalement la souplesse de chacune des deux grandes chaînes. Les membres inférieurs explorent l'extension, les membres supérieurs la flexion.","s":0},{"q":"Quelles sont les composantes de la 1ʳᵉ diagonale du membre supérieur en flexion ?","o":["Flexion, adduction, rotation externe ; poignet et doigts fléchis, déviation radiale","Flexion, abduction, rotation externe ; poignet et doigts tendus, déviation radiale","Extension, abduction, rotation interne ; poignet et doigts tendus, déviation cubitale","Extension, adduction, rotation interne ; poignet et doigts fléchis, déviation cubitale"],"r":0,"e":"La commande est : « Serrez ma main, pliez votre poignet, amenez votre bras vers le haut et vers l'intérieur ».","s":1},{"q":"Quelles sont les composantes de la 1ʳᵉ diagonale du membre supérieur en extension ?","o":["Extension, abduction, rotation interne ; poignet et doigts tendus, déviation cubitale","Extension, adduction, rotation interne ; poignet et doigts fléchis, déviation cubitale","Flexion, adduction, rotation externe ; poignet et doigts fléchis, déviation radiale","Flexion, abduction, rotation externe ; poignet et doigts tendus, déviation radiale"],"r":0,"e":"La commande est : « Tendez vos doigts, tendez votre poignet et amenez votre bras vers le bas et vers l'extérieur ».","s":1},{"q":"Quelles sont les composantes de la 2ᵉ diagonale du membre supérieur en flexion ?","o":["Flexion, abduction, rotation externe ; poignet et doigts tendus, déviation radiale","Flexion, adduction, rotation externe ; poignet et doigts fléchis, déviation radiale","Extension, adduction, rotation interne ; poignet et doigts fléchis, déviation cubitale","Extension, abduction, rotation interne ; poignet et doigts tendus, déviation cubitale"],"r":0,"e":"L'omoplate réalise une rotation supérieure, une adduction et une élévation.","s":1},{"q":"Quelles sont les composantes de la 2ᵉ diagonale du membre supérieur en extension ?","o":["Extension, adduction, rotation interne ; poignet et doigts fléchis, déviation cubitale","Extension, abduction, rotation interne ; poignet et doigts tendus, déviation cubitale","Flexion, abduction, rotation externe ; poignet et doigts tendus, déviation radiale","Flexion, adduction, rotation externe ; poignet et doigts fléchis, déviation radiale"],"r":0,"e":"L'omoplate réalise une rotation inférieure, une abduction et un abaissement.","s":1},{"q":"Quel est le mouvement de l'avant-bras dans la 1ʳᵉ diagonale MS en flexion ?","o":["Supination","Pronation","Position neutre","Rotation externe"],"r":0,"e":"Le muscle impliqué est le court supinateur.","s":1},{"q":"Quel muscle de l'omoplate intervient dans la 1ʳᵉ diagonale MS en flexion ?","o":["Le grand dentelé","Les rhomboïdes","Le trapèze","Le petit pectoral"],"r":0,"e":"En 1ʳᵉ extension, ce sont l'élévateur de l'omoplate et les rhomboïdes.","s":1},{"q":"Quels muscles de l'épaule interviennent dans la 1ʳᵉ diagonale MS en extension ?","o":["Grand rond, grand dorsal, deltoïde postérieur, longue portion du triceps","Grand pectoral claviculaire, deltoïde antérieur, coraco-brachial, biceps","Petit rond, supra-épineux, infra-épineux, deltoïde moyen","Grand pectoral sternal, sous-scapulaire, petit pectoral, subclavier"],"r":0,"e":"La 1ʳᵉ flexion mobilise le grand pectoral claviculaire, le deltoïde antérieur, le coraco-brachial et le biceps.","s":1},{"q":"Quels muscles de l'épaule interviennent dans la 2ᵉ diagonale MS en flexion ?","o":["Petit rond, supra-épineux, infra-épineux, deltoïde moyen","Grand pectoral sternal, sous-scapulaire, grand rond, triceps","Grand rond, grand dorsal, deltoïde postérieur, triceps","Coraco-brachial, biceps, deltoïde antérieur, grand pectoral"],"r":0,"e":"Le muscle de l'omoplate est le trapèze.","s":1},{"q":"Quels muscles interviennent à l'omoplate dans la 2ᵉ diagonale MS en extension ?","o":["Petit pectoral et subclavier","Trapèze moyen et supérieur","Grand dentelé et angulaire","Rhomboïdes et trapèze inférieur"],"r":0,"e":"L'épaule mobilise le grand pectoral (portion sternale) et le sous-scapulaire.","s":1},{"q":"Quel muscle du poignet intervient dans la 2ᵉ diagonale MS en flexion ?","o":["Le long et le court extenseur radial du carpe","Le fléchisseur ulnaire du carpe et le petit palmaire","L'extenseur ulnaire du carpe","Le fléchisseur radial du carpe"],"r":0,"e":"L'avant-bras est mobilisé par le long supinateur (brachio-radial).","s":1},{"q":"Quel est le contact manuel de la 1ʳᵉ diagonale MS en flexion (MSG) ?","o":["Main droite sur la face palmaire, main gauche en pince sur l'avant-bras","Main droite sur la face dorsale, main gauche en pince sur la face postérieure du bras","Les deux mains sur le moignon de l'épaule, en prise globale","Une main sur le coude, l'autre sur le bord médial de la scapula"],"r":0,"e":"En 1ʳᵉ extension, la main droite se place sur la face dorsale. La pince de la main gauche se place à la région antérieure de l'avant-bras.","s":1},{"q":"Comment se déroule une diagonale avec extension du coude ?","o":["Le départ inclut la flexion du coude, l'arrivée est celle de la diagonale simple","Le départ est celui de la diagonale simple, l'arrivée inclut la flexion du coude","Le départ et l'arrivée sont ceux de la diagonale simple, avec d'autres contacts","Le départ et l'arrivée gardent le coude immobile en extension"],"r":0,"e":"À l'inverse, avec flexion du coude, la position initiale est identique à la diagonale simple.","s":1},{"q":"Quels muscles assurent l'extension du coude dans les variantes ?","o":["Triceps et anconé","Biceps et brachial antérieur","Long supinateur","Rond pronateur"],"r":0,"e":"La flexion du coude mobilise le biceps et le brachial antérieur.","s":1},{"q":"Quelles sont les composantes de la 1ʳᵉ diagonale du membre inférieur en flexion ?","o":["Flexion, adduction et rotation externe de hanche, flexion dorsale et inversion","Flexion, abduction et rotation interne de hanche, flexion dorsale et éversion","Extension, abduction et rotation interne de hanche, flexion plantaire et éversion","Extension, adduction et rotation externe de hanche, flexion plantaire et inversion"],"r":0,"e":"Le pied et les orteils sont en extension.","s":1},{"q":"Quelles sont les composantes de la 2ᵉ diagonale du membre inférieur en flexion ?","o":["Flexion, abduction et rotation interne de hanche, flexion dorsale et éversion","Flexion, adduction et rotation externe de hanche, flexion dorsale et inversion","Extension, abduction et rotation interne de hanche, flexion plantaire et éversion","Extension, adduction et rotation externe de hanche, flexion plantaire et inversion"],"r":0,"e":"La 1ʳᵉ flexion MI associe adduction et rotation externe avec inversion.","s":1},{"q":"Quelles sont les composantes de la 2ᵉ diagonale du membre inférieur en extension ?","o":["Extension, adduction et rotation externe de hanche, flexion plantaire et inversion","Extension, abduction et rotation interne de hanche, flexion plantaire et éversion","Flexion, adduction et rotation externe de hanche, flexion dorsale et inversion","Flexion, abduction et rotation interne de hanche, flexion dorsale et éversion"],"r":0,"e":"La 1ʳᵉ extension MI associe abduction et rotation interne avec éversion.","s":1},{"q":"Quelle est la commande verbale de la 1ʳᵉ diagonale MI en flexion ?","o":["« Tendez vos orteils, pied et talon vers l'intérieur, jambe vers le haut et l'intérieur »","« Pliez vos orteils, pied et talon vers l'extérieur, jambe vers le bas et l'extérieur »","« Tendez vos orteils, pied et talon vers l'extérieur, jambe vers le haut et l'extérieur »","« Pliez vos orteils, pied et talon vers l'intérieur, jambe vers le bas et l'intérieur »"],"r":0,"e":"En extension, la commande est « Pliez vos orteils, amenez votre pied vers l'extérieur… ». Formule complète : « Tendez vos orteils, amenez le pied vers l'intérieur, tournez le talon vers l'intérieur et amenez votre jambe vers le haut et vers l'intérieur ».","s":1},{"q":"Quels muscles de la hanche interviennent dans la 1ʳᵉ diagonale MI en flexion ?","o":["Psoas-iliaque, obturateur externe, pectiné, adducteurs, droit antérieur","Grand fessier, ischio-jambiers, grand adducteur, piriforme, carré fémoral","Moyen fessier, petit fessier, TFL, sartorius","Piriforme, obturateur interne, jumeaux, carré fémoral"],"r":0,"e":"À la tibio-tarsienne, on retrouve notamment le tibial antérieur et les extenseurs des orteils. Adducteurs : court et long.","s":1},{"q":"Quels muscles du genou interviennent dans la 1ʳᵉ diagonale MI en flexion avec flexion du genou ?","o":["Semi-membraneux, semi-tendineux et couturier","Quadriceps, avec le droit antérieur et les vastes","Gastrocnémiens et plantaire grêle","Poplité, biceps fémoral et gracile"],"r":0,"e":"Avec extension du genou, c'est le quadriceps qui est mobilisé.","s":1},{"q":"Quel est le contact manuel de la 1ʳᵉ diagonale MI en extension (MID) ?","o":["Main droite sur la plante du pied, main gauche en arrière et en dehors de la cuisse","Main droite sur le dos et le bord interne du pied, main gauche sur la face antérieure de la cuisse","Les deux mains sur le bassin, de part et d'autre des EIAS","Une main sur le genou, l'autre sur la crête iliaque homolatérale"],"r":0,"e":"En 1ʳᵉ flexion, la main droite se place sur la face dorsale et interne du pied. La main droite prend aussi les orteils.","s":1},{"q":"Où se place la main du maxillaire dans la diagonale de flexion avec rotation de la tête ?","o":["Du côté de la rotation","Du côté opposé à la rotation","Sur l'occiput","Sur le sternum"],"r":0,"e":"En extension avec rotation, la main du maxillaire est opposée à celle de la rotation.","s":1},{"q":"Quel mouvement de la mandibule accompagne la diagonale de flexion cervicale ?","o":["L'abaissement","L'élévation","La latéralité","Aucun mouvement"],"r":0,"e":"En extension, la mandibule s'élève.","s":1},{"q":"Quels muscles interviennent dans la diagonale de flexion de la tête et du cou ?","o":["Sterno-cléido-mastoïdien, scalènes, droits de la tête","Complexus, splénius, transversaire du cou, multifides","Trapèze inférieur, rhomboïdes et angulaire de la scapula","Grand dorsal, grand rond et dentelé postérieur supérieur"],"r":0,"e":"La mandibule mobilise les supra-hyoïdiens et les infra-hyoïdiens. Les droits de la tête : grand et petit droit antérieur, droit latéral.","s":1},{"q":"Quels muscles interviennent dans la diagonale d'extension de la tête et du cou ?","o":["Complexus, splénius, transversaire du cou, trapèze supérieur","SCM, scalènes, grand et petit droit antérieur de la tête","Supra-hyoïdiens, infra-hyoïdiens, droit latéral et long du cou","Grand dentelé, trapèze inférieur, rhomboïdes et angulaire"],"r":0,"e":"La mandibule mobilise le splénius et les grand et petit droit postérieur de la tête. Ainsi que les interépineux et les multifides.","s":1},{"q":"Que désigne le chopping ?","o":["Bilatérale asymétrique vers l'extension, tronc supérieur fléchi, rotation","Bilatérale asymétrique vers la flexion, tronc supérieur étendu, rotation","Unilatérale du membre inférieur, vers l'extension, avec rotation","Technique de relâchement après contraction maximale, en rotation"],"r":0,"e":"Les membres supérieurs réalisent les 1ʳᵉ et 2ᵉ diagonales vers l'extension.","s":1},{"q":"Que désigne le lifting ?","o":["Bilatérale asymétrique vers la flexion, tronc supérieur étendu, rotation","Bilatérale asymétrique vers l'extension, tronc supérieur fléchi, rotation","Unilatérale du membre inférieur, vers la flexion, avec rotation","Test de proprioception du tronc, en rotation et en extension"],"r":0,"e":"Les membres supérieurs réalisent les 1ʳᵉ et 2ᵉ diagonales vers la flexion.","s":1},{"q":"Quelle est la commande verbale du chopping ?","o":["« Amenez vos bras vers le bas et vers la droite, regardez votre main »","« Amenez vos bras vers le haut et vers la gauche, regardez votre main »","« Serrez ma main, pliez votre poignet, amenez le bras vers le haut »","« Tendez vos orteils, amenez le pied vers l'intérieur et vers le haut »"],"r":0,"e":"Le lifting demande d'amener les bras vers le haut. La tête accompagne le mouvement.","s":1},{"q":"Quels muscles du dorsal interviennent dans le lifting ?","o":["Muscles postérieurs : transversaire épineux, ilio-costal, multifides","Muscles antérieurs : obliques, droit de l'abdomen, intercostaux internes","Muscles du cou : SCM, scalènes, droits antérieurs et latéral de la tête","Muscles de la ceinture : grand dentelé, petit pectoral, rhomboïdes"],"r":0,"e":"Le chopping mobilise les obliques, le droit de l'abdomen, les intercostaux internes et le carré des lombes. Avec aussi le carré des lombes, les interépineux, les intertransversaires et le transverse de l'abdomen.","s":1},{"q":"Combien de diagonales existe-t-il pour chaque partie du corps ?","o":["Deux, chacune avec un schéma de flexion et un d'extension","Une seule, avec un schéma de flexion et un d'extension","Trois, chacune avec un schéma de flexion et un d'extension","Quatre, chacune avec un schéma en rotation interne et un en rotation externe"],"r":0,"e":"Les schémas combinent des composantes dans les trois plans.","s":1},{"q":"Quel mouvement du poignet accompagne la 2ᵉ diagonale MS en extension ?","o":["Flexion avec déviation cubitale","Extension avec déviation radiale","Flexion avec déviation radiale","Extension avec déviation cubitale"],"r":0,"e":"L'avant-bras est en pronation et le muscle est le fléchisseur ulnaire du carpe avec le long palmaire.","s":1},{"q":"Dans la 1ʳᵉ diagonale du membre inférieur en extension, les composantes sont :","o":["Extension, abduction et rotation interne de hanche, flexion plantaire et éversion","Extension, adduction et rotation externe de hanche, flexion plantaire et inversion","Flexion, adduction et rotation externe de hanche, flexion dorsale et inversion","Flexion, abduction et rotation interne de hanche, flexion dorsale et éversion"],"r":0,"e":"La 2ᵉ diagonale en extension associe extension, adduction et rotation externe de hanche, avec flexion plantaire et inversion.","s":1},{"q":"Dans la 1ʳᵉ diagonale du membre supérieur en flexion, le pouce réalise :","o":["Une extension et une abduction, avec rotation vers le côté cubital","Une flexion et une adduction, avec rotation sur le 2ᵉ métacarpien","Une opposition pure, vers la base du 5ᵉ doigt","Une extension pure, sans abduction ni rotation"],"r":1,"e":"En extension, il réalise au contraire une extension avec abduction et rotation vers le côté cubital.","s":1},{"q":"Dans la 1ʳᵉ diagonale MS en flexion, l'omoplate réalise :","o":["Une rotation inférieure, une adduction et un abaissement","Une rotation supérieure, une abduction et une élévation","Une rétraction pure, sans rotation ni élévation","Une élévation isolée, sans rotation ni abduction"],"r":1,"e":"En extension, elle réalise l'inverse : rotation inférieure, adduction et abaissement.","s":1},{"q":"La commande verbale de la 1ʳᵉ diagonale MS en extension est :","o":["« Serrez ma main, pliez votre poignet, amenez votre bras vers le haut et vers l'intérieur »","« Tendez vos doigts, tendez votre poignet et amenez votre bras vers le bas et vers l'extérieur »","« Tendez vos doigts, amenez votre bras vers le haut et vers l'extérieur »","« Serrez ma main et amenez votre bras vers le bas et vers l'intérieur »"],"r":1,"e":"Chaque commande décrit successivement le distal puis le proximal, ce qui reproduit la séquence de recrutement du schéma.","s":1},{"q":"Dans la 1ʳᵉ diagonale MS en flexion, l'avant-bras réalise :","o":["Une pronation","Une supination","Une position neutre","Une rotation alternée"],"r":1,"e":"La supination accompagne la rotation externe d'épaule et la déviation radiale du poignet : le schéma est cohérent sur toute la chaîne.","s":1},{"q":"Le muscle de l'omoplate intervenant dans la 1ʳᵉ diagonale MS en flexion est :","o":["Le grand dentelé","Les rhomboïdes","L'élévateur de l'omoplate","Le trapèze moyen"],"r":0,"e":"En extension interviennent l'élévateur de l'omoplate et les rhomboïdes, qui produisent rotation inférieure et adduction.","s":1},{"q":"Les muscles de l'épaule de la 1ʳᵉ diagonale MS en extension sont :","o":["Le grand pectoral claviculaire, le deltoïde antérieur, le coraco-brachial","Le grand rond, le grand dorsal, le deltoïde postérieur, la longue portion du triceps","Le supra-épineux, l'infra-épineux, le petit rond, le deltoïde moyen","Le petit pectoral, le subclavier, le grand pectoral sternal, le sous-scapulaire"],"r":1,"e":"Les premiers cités interviennent dans la 1ʳᵉ diagonale en flexion, où ils produisent flexion, adduction et rotation externe.","s":1},{"q":"Le muscle du poignet de la 1ʳᵉ diagonale MS en extension est :","o":["Le fléchisseur radial du carpe","L'extenseur ulnaire du carpe","Le long palmaire","Le court supinateur"],"r":1,"e":"En flexion interviennent le fléchisseur radial du carpe, ou grand palmaire, et le long palmaire, cohérents avec la déviation radiale.","s":1},{"q":"Le muscle de l'avant-bras de la 1ʳᵉ diagonale MS en extension est :","o":["Le court supinateur","Le carré pronateur","Le long supinateur","Le rond pronateur uniquement"],"r":1,"e":"Le court supinateur intervient en flexion, en cohérence avec la supination du schéma.","s":1},{"q":"Dans la 2ᵉ diagonale MS en flexion, le poignet réalise :","o":["Une flexion avec déviation cubitale","Une extension avec déviation radiale","Une flexion avec déviation radiale","Une extension avec déviation cubitale"],"r":1,"e":"En 2ᵉ extension, il réalise une flexion avec déviation cubitale : les deux schémas sont strictement antagonistes.","s":1},{"q":"Dans la 2ᵉ diagonale MS en flexion, l'omoplate réalise :","o":["Une rotation supérieure, une adduction et une élévation","Une rotation inférieure, une abduction et un abaissement","Une rotation supérieure, une abduction et une élévation","Une rotation inférieure, une adduction et un abaissement"],"r":0,"e":"La différence avec la 1ʳᵉ diagonale porte sur l'adduction scapulaire, cohérente avec l'abduction d'épaule du schéma.","s":1},{"q":"La commande verbale de la 2ᵉ diagonale MS en flexion est :","o":["« Serrez ma main, pliez le poignet, amenez le bras en bas et en dedans »","« Tendez les doigts, tendez le poignet, amenez le bras en haut et en dehors »","« Serrez ma main, pliez le poignet, amenez le bras en haut et en dedans »","« Tendez les doigts, tendez le poignet, amenez le bras en bas et en dehors »"],"r":1,"e":"La 2ᵉ extension inverse la formule : serrer la main, plier le poignet, amener le bras vers le bas et vers l'intérieur.","s":1},{"q":"Dans la 2ᵉ diagonale du membre inférieur en flexion, les composantes sont :","o":["Flexion + adduction + rotation externe, flexion dorsale + inversion","Flexion + abduction + rotation interne, flexion dorsale + éversion","Extension + abduction + rotation interne","Extension + adduction + rotation externe"],"r":1,"e":"La 1ʳᵉ diagonale en flexion associe au contraire flexion, adduction et rotation externe, avec flexion dorsale et inversion.","s":1},{"q":"Dans une diagonale avec extension du coude, les muscles sollicités sont principalement :","o":["Le biceps et le brachial","Le triceps et l'anconé","Le brachio-radial","Le carré pronateur"],"r":1,"e":"Les variantes avec flexion ou extension du coude exploitent la liberté de l'articulation intermédiaire, tandis que proximal et distal restent liés au schéma.","s":1},{"q":"Dans la diagonale de flexion de la tête et du cou avec rotation, la main du maxillaire se place :","o":["Du côté de la rotation","Du côté opposé à la rotation","Sur le front","Sur l'occiput"],"r":0,"e":"En extension avec rotation, la main du maxillaire se place au contraire du côté opposé à la rotation.","s":1},{"q":"Le chopping correspond à :","o":["Une diagonale bilatérale asymétrique vers la flexion, tronc étendu","Une diagonale bilatérale asymétrique vers l'extension, tronc fléchi","Une diagonale unilatérale du membre supérieur, tronc fixé","Une diagonale du membre inférieur, tronc en rotation"],"r":1,"e":"Le lifting est son symétrique : bilatéral asymétrique vers la flexion, avec extension du tronc supérieur et rotation. Le tronc supérieur se fléchit avec rotation.","s":1},{"q":"Le lifting associe :","o":["Une flexion du tronc supérieur avec rotation","Une extension du tronc supérieur avec rotation","Une flexion latérale pure","Une rotation isolée"],"r":1,"e":"Ces deux schémas bilatéraux asymétriques permettent de solliciter le tronc à partir des membres supérieurs, ce qui est précieux en rééducation neurologique.","s":1},{"q":"Dans la 2ᵉ diagonale MS en extension, le poignet accompagne le mouvement par :","o":["Une extension avec déviation radiale","Une flexion avec déviation cubitale","Une extension avec déviation cubitale","Une flexion avec déviation radiale"],"r":1,"e":"Elle est cohérente avec l'adduction et la rotation interne d'épaule ainsi qu'avec la pronation de l'avant-bras.","s":1},{"q":"Le contact manuel de la 1ʳᵉ diagonale MS en flexion, pour un membre supérieur gauche, consiste à placer :","o":["La main droite sur la face dorsale, la gauche à l'arrière du bras","La main droite sur la face palmaire, la gauche en pince sur l'avant-bras","Les deux mains sur le moignon de l'épaule, en prise globale","Une main sur le coude, l'autre sur l'angle inférieur de la scapula"],"r":1,"e":"En extension, la main droite se place sur la face dorsale : le contact suit toujours la direction du mouvement demandé. La pince se place à la face antérieure de l'avant-bras.","s":1},{"q":"Dans la 2ᵉ diagonale MS en extension, l'avant-bras réalise :","o":["Une supination","Une pronation","Une position neutre","Une rotation libre"],"r":1,"e":"Elle accompagne la rotation interne d'épaule et la déviation cubitale du poignet. En 2ᵉ flexion, c'est la supination qui accompagne la rotation externe.","s":1},{"q":"Quel est l'objectif général des techniques spécifiques de PNF ?","o":["Favoriser le mouvement fonctionnel : faciliter, inhiber, renforcer, relâcher","Augmenter la force maximale : charger, répéter, progresser, fatiguer","Étirer passivement les chaînes : allonger, maintenir, relâcher, répéter","Diminuer la douleur : masser, chauffer, immobiliser, reposer"],"r":0,"e":"On utilise des contractions combinées à une résistance adaptée, dans des schémas ajustés à chaque patient.","s":2},{"q":"Quelles techniques mettent l'emphase sur l'agoniste ?","o":["Les contractions répétées et les initiations rythmiques","Le slow reversal et les stabilisations rythmiques","Le contracter-relâcher et le tenir-relâcher","Uniquement les stabilisations rythmiques"],"r":0,"e":"Le slow reversal et les stabilisations rythmiques mettent l'emphase sur l'antagoniste.","s":2},{"q":"Quelles techniques mettent l'emphase sur l'antagoniste pour faciliter l'agoniste ?","o":["Le slow reversal et les stabilisations rythmiques","Les contractions répétées et les initiations rythmiques","Le contracter-relâcher et le tenir-relâcher","Les diagonales de tronc"],"r":0,"e":"Les techniques de relâchement de l'antagoniste sont le contracter-relâcher et le tenir-relâcher.","s":2},{"q":"Que ne doit pas faire le patient pendant l'étirement des contractions répétées ?","o":["Se relâcher","Respirer","Regarder le mouvement","Parler"],"r":0,"e":"La technique repose sur le principe de renforcement et sur le réflexe d'étirement.","s":2},{"q":"Sur quels principes reposent les contractions répétées ?","o":["Le principe de renforcement et le réflexe d'étirement","L'innervation réciproque et l'inhibition de l'antagoniste","Le relâchement après une contraction maximale","L'apprentissage moteur passif par la visualisation"],"r":0,"e":"Elles potentialisent la force réalisée par les muscles faibles.","s":2},{"q":"Quels sont les objectifs des contractions répétées ?","o":["Initier le mouvement, gagner en amplitude active et en force, le diriger","Gagner en amplitude passive, par étirement lent et prolongé de l'antagoniste","Améliorer la stabilité, l'équilibre, par co-contraction","Relâcher l'antagoniste raccourci, par contracter-relâcher"],"r":0,"e":"Elles s'indiquent en cas de manque de force, de fatigue ou de difficulté à initier le mouvement.","s":2},{"q":"Quelles sont les contre-indications des contractions répétées ?","o":["Douleur, instabilité, fracture, ostéoporose, lésion musculaire","Fatigue, manque de force, difficulté à initier ou à diriger le mouvement","Défaut de représentation du mouvement, trouble de coordination","Limitation articulaire d'origine musculaire, raideur, rétraction"],"r":0,"e":"Ces contre-indications sont communes à plusieurs techniques spécifiques.","s":2},{"q":"Comment applique-t-on l'étirement initial dans les contractions répétées ?","o":["Rapide et doux, sur le schéma agoniste en position d'allongement","Lent et prolongé, sur le schéma antagoniste en position raccourcie","Fort et bref, en fin d'amplitude du schéma agoniste seulement","Rapide et fort, sans consigne verbale associée au réflexe"],"r":0,"e":"Une consigne de contraction volontaire est donnée simultanément à la réponse réflexe.","s":2},{"q":"Que fait-on lorsqu'on identifie le manque de force au cours de l'amplitude ?","o":["Étirements rapides vers l'antagoniste, puis isotonique dans l'agoniste","Arrêt de l'exercice, puis reprise du schéma au début de l'amplitude","Passage en isométrique, au point faible, sans aucune reprise du mouvement","Résistance maximale sans mouvement, puis relâchement complet"],"r":0,"e":"Le schéma est réalisé avec la résistance maximale permettant le mouvement.","s":2},{"q":"Comment progressent les initiations rythmiques ?","o":["Du passif à l'actif, puis au résisté","Du résisté à l'actif, puis au passif","De l'actif au résisté, sans passif","De l'isométrique au passif, sans actif"],"r":0,"e":"Elles reposent sur l'apprentissage et la représentation des mouvements par le SNC.","s":2},{"q":"Quels stimuli utilisent les initiations rythmiques ?","o":["La visualisation et la verbalisation","L'étirement rapide et le réflexe myotatique","La compression et la traction articulaires","La stimulation électrique et la vibration"],"r":0,"e":"Elles reposent sur le processus d'apprentissage et de représentation du mouvement par le SNC.","s":2},{"q":"Quels sont les objectifs des initiations rythmiques ?","o":["Faciliter le schéma, la coordination, le rythme, réapprendre le mouvement","Gagner en amplitude passive, par étirement lent et prolongé de l'antagoniste","Relâcher les antagonistes raccourcis, par contracter-relâcher","Augmenter la stabilité, par co-contraction isométrique"],"r":0,"e":"Elles s'indiquent en cas de difficulté à initier le mouvement ou de fatigue. Elles améliorent aussi la perception du mouvement.","s":2},{"q":"Quelle est la 2ᵉ étape technique des initiations rythmiques ?","o":["Faire passivement le schéma altéré, avec commande verbale et sensation","Appliquer d'emblée une résistance maximale sur le schéma altéré","Réaliser le schéma antagoniste, contre résistance","Demander une contraction isométrique, au point faible"],"r":0,"e":"On sollicite ensuite une collaboration de plus en plus active du patient.","s":2},{"q":"En quoi consiste le slow reversal ?","o":["Antagoniste lent et maximal jusqu'en fin d'amplitude, puis agoniste lent","Contraction isométrique des deux schémas, en alternance rapide","Étirement passif prolongé de l'antagoniste, puis relâchement","Étirements rapides répétés de l'agoniste, puis contraction isotonique"],"r":0,"e":"Il repose sur le principe de renforcement et de relâchement après contraction maximale. Les deux contractions sont dynamiques.","s":2},{"q":"Quelle indication est spécifique du slow reversal ?","o":["La difficulté à changer de direction de façon coordonnée","La limitation articulaire d'origine musculaire","L'instabilité articulaire après une entorse ou une luxation","La diminution de l'amplitude passive"],"r":0,"e":"Il s'indique aussi en cas de manque de force et de fatigue.","s":2},{"q":"Comment réalise-t-on le schéma agoniste dans le slow reversal ?","o":["Sans résistance, après avoir changé le contact, surtout en distal","Avec une résistance maximale, sans changer le contact manuel","En isométrique, au point d'amplitude où le patient est faible","En passif complet, le patient restant totalement relâché"],"r":0,"e":"Le schéma antagoniste est en revanche réalisé avec une résistance maximale permettant le mouvement.","s":2},{"q":"Comment sont enchaînées les procédures du slow reversal ?","o":["Plusieurs fois de suite, lentement et sans interruption","Une seule fois, puis on passe à une autre technique","Rapidement, par à-coups, pour solliciter le réflexe","Avec des pauses de 30 secondes entre chaque inversion"],"r":0,"e":"On commence toujours par identifier le schéma faible (agoniste).","s":2},{"q":"Sur quel processus reposent les stabilisations rythmiques ?","o":["L'innervation réciproque","Le réflexe d'étirement","Le relâchement après contraction maximale","La sommation temporelle"],"r":0,"e":"Elles associent des contractions isométriques des schémas agoniste et antagoniste, avec co-contraction.","s":2},{"q":"Quel type de contraction caractérise les stabilisations rythmiques ?","o":["Des contractions isométriques des schémas agoniste et antagoniste","Des contractions isotoniques concentriques du schéma agoniste seul","Des contractions excentriques lentes du schéma antagoniste","Des étirements passifs alternés des deux schémas"],"r":0,"e":"Elles exigent momentanément une co-contraction.","s":2},{"q":"Quels sont les objectifs des stabilisations rythmiques ?","o":["Gagner en amplitude active, en force, en stabilité et en équilibre","Gagner en amplitude passive seule, par étirement prolongé","Relâcher l'antagoniste raccourci, par contracter-relâcher","Normaliser le rythme du mouvement, par visualisation et verbalisation"],"r":0,"e":"Elles s'indiquent notamment en cas d'instabilité articulaire.","s":2},{"q":"Quelles sont les contre-indications des stabilisations rythmiques ?","o":["Fractures, ostéoporose et lésions musculaires","Instabilité articulaire, laxité ligamentaire","Faiblesse musculaire, fatigue","Défaut de coordination, de rythme"],"r":0,"e":"L'instabilité articulaire en est au contraire une indication.","s":2},{"q":"Quelle est la 1ʳᵉ étape technique des stabilisations rythmiques ?","o":["Faire le schéma agoniste en isotonique jusqu'au point d'instabilité","Demander d'emblée une contraction isométrique de l'antagoniste","Étirer rapidement l'antagoniste pour déclencher le réflexe","Réaliser le schéma en passif jusqu'en fin d'amplitude, puis tenir la position"],"r":0,"e":"On sollicite ensuite une co-contraction par contraction isométrique de l'antagoniste.","s":2},{"q":"Quel est l'objectif du contracter-relâcher et du tenir-relâcher ?","o":["Augmenter l'amplitude passive de mouvement","Augmenter la force maximale de l'agoniste","Améliorer la coordination du schéma","Faciliter l'initiation du mouvement chez le patient lent"],"r":0,"e":"Leur indication est la limitation articulaire d'origine musculaire.","s":2},{"q":"Quelle est l'indication du contracter-relâcher ?","o":["La limitation articulaire d'origine musculaire","L'instabilité articulaire d'origine ligamentaire","La fatigue et le manque de force en fin d'amplitude","La difficulté à initier le mouvement"],"r":0,"e":"Les contre-indications sont la douleur aiguë, l'instabilité, les fractures, l'ostéoporose et les lésions musculaires.","s":2},{"q":"Quel type de contraction utilise le contracter-relâcher ?","o":["Une contraction isotonique maximale de l'antagoniste","Une contraction isométrique de l'antagoniste","Une contraction excentrique lente de l'agoniste","Aucune contraction, un étirement passif seul"],"r":0,"e":"Le tenir-relâcher utilise une contraction isométrique à la limite de l'amplitude disponible. Isotonique = dynamique.","s":2},{"q":"Qu'est-ce qui distingue le tenir-relâcher du contracter-relâcher ?","o":["L'antagoniste se contracte en isométrique, à la limite de l'amplitude","La contraction de l'antagoniste dure plus longtemps, en isotonique","Il n'y a pas de phase de relâchement après la contraction maximale","Le mouvement agoniste n'est pas réalisé après le relâchement"],"r":0,"e":"Les deux techniques reposent sur le principe du relâchement après contraction maximale.","s":2},{"q":"Sur quel principe reposent le contracter-relâcher et le tenir-relâcher ?","o":["Le relâchement après contraction maximale","Le réflexe d'étirement de l'agoniste","L'innervation réciproque des antagonistes","La sommation spatiale et temporelle des stimuli"],"r":0,"e":"Leur objectif est d'augmenter l'amplitude passive de mouvement.","s":2},{"q":"Quelle est la première étape du contracter-relâcher ?","o":["Réaliser le schéma agoniste limité, pour l'identifier","Contracter immédiatement l'antagoniste, en isométrique","Étirer passivement le muscle raccourci, de façon prolongée","Réaliser une co-contraction des deux schémas, au point limité"],"r":0,"e":"On réalise ensuite, à partir de cette amplitude, une contraction isotonique maximale du schéma antagoniste.","s":2},{"q":"Après la contraction du muscle raccourci, que fait-on ?","o":["On sollicite le relâchement puis on fait l'agoniste jusqu'à la limitation","On répète immédiatement la contraction maximale de l'antagoniste","On applique une résistance maximale à l'agoniste en fin d'amplitude","On termine la séance pour laisser le muscle raccourci récupérer au repos"],"r":0,"e":"Le but est d'allonger le muscle raccourci. Le mouvement agoniste peut être actif ou passif.","s":2},{"q":"Quelle contre-indication est spécifique au contracter-relâcher et au tenir-relâcher ?","o":["La douleur aiguë","La fatigue","La faiblesse musculaire","La diminution de la coordination"],"r":0,"e":"S'y ajoutent l'instabilité articulaire, les fractures, l'ostéoporose et les lésions musculaires.","s":2},{"q":"Les techniques spécifiques de PNF utilisent des contractions musculaires combinées :","o":["À une immobilisation, dans des schémas rectilignes standardisés","À une résistance adaptée, dans des schémas ajustés à chaque patient","À un étirement passif seul, dans des schémas analytiques","À une stimulation électrique, dans des schémas ajustés à chaque muscle"],"r":1,"e":"Leur objectif est de favoriser le mouvement fonctionnel par la facilitation, l'inhibition, le renforcement et le relâchement de groupes musculaires.","s":2},{"q":"Les techniques de relâchement de l'antagoniste sont :","o":["Les contractions répétées et les initiations rythmiques","Le slow reversal et les stabilisations rythmiques","Le contracter-relâcher et le tenir-relâcher","Les diagonales et le chopping"],"r":2,"e":"Les deux premières familles mettent l'emphase sur l'agoniste, puis sur l'antagoniste pour faciliter l'agoniste.","s":2},{"q":"Les contre-indications communes aux techniques spécifiques comprennent :","o":["La douleur, l'instabilité, les fractures, l'ostéoporose, les lésions musculaires","La fatigue, le manque de force et la difficulté à initier le mouvement","L'âge avancé, le surpoids et la sédentarité du patient","Le manque de motivation, l'anxiété et la peur du mouvement, chez le patient âgé"],"r":0,"e":"Toutes ces situations ont en commun d'être aggravées par une résistance ou un étirement, qui sont précisément les outils de la méthode.","s":2},{"q":"Les contractions répétées reposent sur :","o":["Le principe de renforcement et le réflexe d'étirement","L'innervation réciproque et l'inhibition de l'antagoniste","L'inhibition autogène et le relâchement post-contraction","La visualisation et la verbalisation du mouvement"],"r":0,"e":"Le renforcement consiste à potentialiser la force des muscles faibles ; le réflexe d'étirement facilite la réponse contractile.","s":2},{"q":"Pendant l'étirement des contractions répétées, le patient :","o":["Doit se relâcher complètement","Ne doit pas se relâcher","Doit retenir sa respiration","Doit fermer les yeux"],"r":1,"e":"Le maintien du tonus est ce qui permet au réflexe d'étirement de s'ajouter à la contraction volontaire au lieu de la remplacer.","s":2},{"q":"Lorsqu'on identifie un manque de force au cours de l'amplitude, on réalise :","o":["Un arrêt de l'exercice, puis une reprise du schéma depuis la position de départ","Des étirements rapides vers l'antagoniste, puis de l'isotonique en agoniste","Une contraction isométrique prolongée au point faible","Un relâchement complet, puis un mouvement passif"],"r":1,"e":"On agit donc précisément là où la faiblesse se manifeste, plutôt que de recommencer tout le mouvement.","s":2},{"q":"Dans la technique de l'étirement initial, la contraction résultante est :","o":["Uniquement réflexe, sans consigne","Uniquement volontaire, sans aucune réponse réflexe","Réflexe et volontaire, si possible résistée","Passive, sans contraction du patient"],"r":2,"e":"La consigne de contraction volontaire est donnée en même temps que l'étirement, de façon à faire coïncider les deux réponses.","s":2},{"q":"Les initiations rythmiques progressent :","o":["Du résisté vers l'actif, puis le passif","Du passif à l'actif, puis au résisté","De l'actif au passif, sans résistance","Sans progression définie à l'avance"],"r":1,"e":"Elles reposent sur le processus d'apprentissage et de représentation des mouvements par le système nerveux central.","s":2},{"q":"Les stimuli utilisés par les initiations rythmiques sont :","o":["La visualisation et la verbalisation","La stimulation électrique et la vibration","La vibration et la compression articulaire","La chaleur et le massage avant le mouvement"],"r":0,"e":"Leurs objectifs sont de faciliter le schéma, d'améliorer coordination et perception du mouvement, de normaliser le rythme et de réapprendre le mouvement.","s":2},{"q":"Parmi les indications des initiations rythmiques figurent :","o":["La difficulté à initier le mouvement et à se le représenter","L'instabilité articulaire après une luxation de l'épaule","La douleur aiguë au moindre mouvement du membre","La fracture récente non consolidée, sous plâtre ou attelle"],"r":0,"e":"S'y ajoutent le manque de force et la présence de fatigue. Les trois dernières propositions sont au contraire des contre-indications.","s":2},{"q":"Les stabilisations rythmiques reposent sur :","o":["Le réflexe d'étirement, par un étirement rapide de l'agoniste","L'innervation réciproque, avec une co-contraction momentanée","La visualisation, par une représentation mentale du mouvement","L'inhibition autogène, par une contraction maximale du muscle"],"r":1,"e":"Cette co-contraction momentanée est ce qui les rend particulièrement adaptées au travail de la stabilité articulaire.","s":2},{"q":"Le type de contraction caractéristique des stabilisations rythmiques est :","o":["Isotonique concentrique","Isométrique","Excentrique","Pliométrique"],"r":1,"e":"Le patient résiste alternativement dans des directions opposées sans qu'aucun mouvement ne se produise.","s":2},{"q":"Le contracter-relâcher utilise une contraction :","o":["Isométrique, à la limite de l'amplitude","Isotonique, ou dynamique, maximale","Excentrique lente, en fin d'amplitude","Passive, sans contraction volontaire"],"r":1,"e":"Le tenir-relâcher utilise au contraire une contraction isométrique à la limite de l'amplitude — c'est la différence essentielle entre les deux.","s":2},{"q":"L'objectif du contracter-relâcher et du tenir-relâcher est :","o":["De renforcer l'agoniste, pour gagner en force","De relâcher l'antagoniste, pour gagner en amplitude","D'améliorer la coordination entre les deux schémas","De normaliser le rythme du mouvement, pour l'automatiser"],"r":1,"e":"Ils constituent la troisième famille de techniques, distincte de celles qui mettent l'emphase sur l'agoniste ou sur l'antagoniste pour faciliter l'agoniste.","s":2},{"q":"Le slow reversal consiste à :","o":["Répéter le même schéma, avec des étirements rapides","Alterner agoniste et antagoniste, de façon continue et résistée","Maintenir une position, par co-contraction isométrique","Étirer passivement l'antagoniste, de façon lente et prolongée"],"r":1,"e":"Il met l'emphase sur l'antagoniste pour faciliter l'agoniste, en exploitant l'induction successive.","s":2},{"q":"Après la contraction du muscle raccourci dans le contracter-relâcher, on procède à :","o":["Un nouvel étirement pour gagner de l'amplitude","Un arrêt de la séance pour éviter la fatigue","Une contraction de l'agoniste seul, contre résistance","Un massage du muscle raccourci, pour finir de le relâcher"],"r":0,"e":"Le relâchement qui suit la contraction ouvre une fenêtre d'inhibition pendant laquelle l'allongement devient possible sans résistance réflexe.","s":2},{"q":"Les initiations rythmiques débutent techniquement par :","o":["Une contraction résistée du schéma faible","L'identification du schéma faible, puis son passage en passif","Un étirement rapide de l'agoniste, puis une contraction","Une co-contraction des deux schémas, au point faible"],"r":1,"e":"La progression passive vers actif puis résisté suit ensuite, à mesure que le patient s'approprie la représentation du mouvement.","s":2},{"q":"Les objectifs des contractions répétées comprennent :","o":["Initier le mouvement, gagner en amplitude active et en force, le diriger","Réduire la douleur, par la chaleur et le relâchement musculaire","Améliorer la respiration, par une meilleure expansion thoracique","Diminuer l'amplitude, pour stabiliser une articulation instable et laxe"],"r":0,"e":"Leurs indications sont le manque de force, la fatigue, la difficulté à initier le mouvement et la diminution de la représentation du mouvement.","s":2},{"q":"La technique des étirements répétés au long de l'amplitude se réalise :","o":["Sans résistance, pour ne pas freiner le mouvement","Avec la résistance maximale qui permet encore le mouvement","En passif, le patient restant relâché","Avec une résistance minimale, pour laisser le mouvement se faire sans effort"],"r":1,"e":"On progresse ainsi jusqu'au point de faiblesse, où l'on applique alors des étirements rapides suivis de contractions isotoniques.","s":2},{"q":"Les objectifs des stabilisations rythmiques sont principalement :","o":["D'augmenter l'amplitude articulaire passive par étirement","D'améliorer la stabilité et le contrôle articulaire","D'initier le mouvement chez le patient lent","De relâcher l'antagoniste raccourci, après une contraction maximale"],"r":1,"e":"Leur nature isométrique et la co-contraction qu'elles imposent en font l'outil de choix pour travailler la stabilité sans mobiliser l'articulation.","s":2},{"q":"Comment définit-on la surveillance de la santé ?","o":["Des contrôles de santé répétés pour repérer les atteintes dues au travail","Un examen unique, à l'embauche, pour vérifier l'aptitude au poste","Un questionnaire annuel de satisfaction des salariés envers leur poste de travail","Un audit financier des dépenses de santé de l'entreprise"],"r":0,"e":"Elle est imposée lorsque les salariés restent exposés à des risques malgré les mesures de prévention.","s":3},{"q":"De quel niveau de prévention relève la surveillance de la santé ?","o":["La prévention secondaire","La prévention primaire","La prévention tertiaire","La prévention quaternaire"],"r":0,"e":"La promotion de la santé relève de la prévention primaire.","s":3},{"q":"Quels symptômes sont les plus rapportés en contexte professionnel ?","o":["L'inconfort et la douleur","Les vertiges","Les troubles digestifs","Les céphalées"],"r":0,"e":"La surveillance vise l'identification précoce des travailleurs à risque de TMS.","s":3},{"q":"Selon Skovlund et al. (2020), à partir de quelle durée d'exposition la capacité de travail diminue-t-elle ?","o":["Plus d'un quart de la journée","Plus de la moitié de la journée","La journée entière","Plus de deux heures seulement"],"r":0,"e":"Cela vaut indépendamment de l'exigence du travail.","s":3},{"q":"Comment définit-on l'inconfort ?","o":["Une perception subjective, liée à la douleur, la fatigue et l'effort","Une lésion structurelle, objectivable à l'imagerie","Une maladie professionnelle, reconnue par la caisse","Un signe clinique, observable et mesurable par l'examinateur à l'examen"],"r":0,"e":"Il est similaire à la sensation ressentie après un exercice physique.","s":3},{"q":"Quel est le statut de l'inconfort par rapport à la douleur ?","o":["C'est un prédicteur de la douleur","C'est une conséquence de la douleur","Il n'a aucun lien avec la douleur","Il exclut la douleur"],"r":0,"e":"Il est utilisé comme outcome subjectif pour des effets à court terme et peut disparaître avec le repos.","s":3},{"q":"Que caractérise le niveau MICRO de surveillance selon Sluiter et al. (2001) ?","o":["Le milieu clinique, pour le diagnostic et le traitement","Le lieu de travail, pour la surveillance active des salariés","Le pays, pour la politique nationale de prévention","Le poste, pour l'analyse ergonomique des tâches"],"r":0,"e":"Le niveau méso correspond à la surveillance active sur le lieu de travail.","s":3},{"q":"Quelles méthodes utilise le niveau MÉSO ?","o":["Questionnaires, entretiens, observation, examen objectif, examens si besoin","Imagerie seule, réalisée pour chaque salarié exposé","Consultations spécialisées seules, à la demande du salarié","Anamnèse seule, recueillie par le médecin du travail, sans examen ni observation"],"r":0,"e":"Il s'agit de la surveillance active de la santé du travailleur sur le lieu de travail.","s":3},{"q":"Quel principe guide le choix des outils de surveillance ?","o":["Trouver un maximum de cas, avec des outils sensibles fondés sur les symptômes","Privilégier la spécificité maximale, pour éviter les faux positifs","Limiter le nombre de cas identifiés, pour ne pas inquiéter les salariés","Utiliser seulement des examens complémentaires, pour objectiver"],"r":0,"e":"On combine évaluations périodiques des symptômes et évaluation objective en contexte réel de travail.","s":3},{"q":"Quel est l'objectif général du protocole SALTSA ?","o":["Un repérage précoce et normalisé des TMS du membre supérieur liés au travail","Une mesure normalisée de la productivité des entreprises européennes, poste par poste","Une évaluation normalisée des risques chimiques au poste de travail","Une standardisation des traitements chirurgicaux des TMS en Europe"],"r":0,"e":"Il facilite le recueil uniforme de données (Van Dyck et al., 2021). Ce système s'applique en Europe.","s":3},{"q":"Que désigne le terme « sentinelle » dans le protocole SALTSA ?","o":["La prévention du développement des TMS du membre supérieur","Un travailleur volontaire qui se prête aux tests","Un signe clinique pathognomonique d'un TMS du membre supérieur lié au travail","Un poste de travail témoin, sans exposition"],"r":0,"e":"Les manœuvres cliniques ont privilégié la sensibilité et la reproductibilité.","s":3},{"q":"Qu'ont privilégié les auteurs de SALTSA pour les manœuvres cliniques ?","o":["La sensibilité et la reproductibilité des tests","La spécificité et la rapidité des tests","Le coût réduit et la grande simplicité des tests","La facilité d'apprentissage des tests"],"r":0,"e":"Toutes les manœuvres présentent des critères de diagnostic différentiel et des photographies.","s":3},{"q":"Comment définit-on le niveau « latent » selon SALTSA ?","o":["Des symptômes présents, mais hors des critères temporels","Des symptômes présents selon les critères temporels, sans signe","Des symptômes et des signes cliniques présents à l'examen","Aucun symptôme, ni aucun signe clinique à l'examen"],"r":0,"e":"Quand les critères temporels ne conviennent pas, on relève le niveau latent comme une alerte.","s":3},{"q":"Comment définit-on le niveau « symptomatique » selon SALTSA ?","o":["Des symptômes selon les critères temporels, sans signe à l'examen","Des symptômes hors des critères temporels, sans signe à l'examen","Des symptômes et des signes cliniques présents à l'examen","Un travailleur en arrêt de travail pour un TMS du membre supérieur"],"r":0,"e":"Le niveau symptomatique avec signes cliniques associe symptômes et signes à l'examen.","s":3},{"q":"Quel est le critère temporel nécessaire pour établir le niveau symptomatique ?","o":["« Actuellement ou au moins 4 jours dans la dernière semaine »","« Au moins 2 jours dans le dernier mois »","« Depuis plus de 6 mois d'évolution »","« Au moins un épisode depuis la prise de poste, quelle que soit sa durée »"],"r":0,"e":"L'autre critère est « présents pendant 4 jours en une semaine au cours des 12 derniers mois ».","s":3},{"q":"Quelle est la composition idéale de l'évaluation de la capacité fonctionnelle pour le travail ?","o":["Multidisciplinaire : médecin du travail, kiné, psychologue si besoin","Unidisciplinaire : médecin du travail seul, sans les autres intervenants","Unidisciplinaire : kiné seul, avec un test de capacité fonctionnelle","Administrative : ressources humaines seules, sur dossier"],"r":0,"e":"Elle considère fonction et structure corporelles, facteurs environnementaux et personnels et état de santé. Elle s'accompagne d'une analyse de la situation de travail.","s":3},{"q":"Quelles fonctions relèvent de la force dynamique évaluée en santé au travail ?","o":["Soulever, porter, tirer, pousser","S'asseoir, s'agenouiller, s'accroupir","Marcher, monter les escaliers, courir","Saisir, pincer, manipuler, coordonner les deux mains"],"r":0,"e":"La capacité de déplacement au poste regroupe s'asseoir, la position debout, s'agenouiller, s'accroupir et se pencher.","s":3},{"q":"Que mesure le Work Ability Index ?","o":["La capacité de travail, selon la santé et les ressources du travailleur","La productivité horaire, selon le poste et les objectifs fixés","Le niveau de douleur, selon une échelle visuelle analogique","Le risque chimique, selon les produits manipulés au poste et leur toxicité connue"],"r":0,"e":"Référence : Ilmarinen, 2006 et 2009.","s":3},{"q":"Comment la capacité de travail est-elle conçue selon Tegland (2011) ?","o":["Une dimension continue, de la pleine capacité à l'incapacité totale","Une variable binaire, apte ou inapte au poste de travail, décidée par le médecin du travail","Un score fixe, établi une seule fois à l'embauche","Une donnée médicale, établie par le seul médecin du travail"],"r":0,"e":"Plus la compétence, la santé, la flexibilité et les stratégies d'adaptation sont élevées, plus la capacité de travail l'est.","s":3},{"q":"Sur quelles périodes le questionnaire nordique (NMQ) interroge-t-il ?","o":["Les 12 derniers mois et/ou les 7 derniers jours","Les 30 derniers jours et/ou les 24 dernières heures","Les 5 dernières années et/ou les 12 derniers mois","La semaine en cours et/ou les 6 mois précédents, depuis l'embauche"],"r":0,"e":"Il dépiste courbatures, douleurs, gêne ou engourdissement (Kuorinka et al., 1994).","s":3},{"q":"Combien de sous-échelles comporte le Job Content Questionnaire de Karasek ?","o":["5","3","7","10"],"r":0,"e":"Exigences psychologiques, latitude décisionnelle, soutien social, exigences physiques et insécurité au travail.","s":3},{"q":"Quelle sous-échelle ne fait PAS partie du JCQ de Karasek ?","o":["La capacité aérobie","La latitude décisionnelle","Le soutien social","L'insécurité au travail"],"r":0,"e":"Les cinq sous-échelles sont exigences psychologiques, latitude décisionnelle, soutien social, exigences physiques et insécurité au travail.","s":3},{"q":"Sur quoi repose le modèle d'exposition physique du membre supérieur distal ?","o":["Intensité, fréquence et durée de l'effort, posture du poignet, durée par jour","La seule force maximale de préhension, mesurée au dynamomètre de Jamar, main dominante","La seule durée quotidienne de la tâche, en heures","L'âge, le sexe et l'ancienneté du travailleur"],"r":0,"e":"L'évaluation du poste distingue la tâche et l'activité. La posture concerne la main et le poignet.","s":3},{"q":"Quelle modalité fait partie de la kinésithérapie on-site selon Hunter (2014) ?","o":["L'identification des barrières au retour au travail","La prescription d'antalgiques adaptés au poste","La rédaction des contrats de travail aménagés","L'audit comptable des arrêts de travail de l'équipe, poste par poste"],"r":0,"e":"S'y ajoutent recommandations, exercices, enseignement de stratégies, « hands-on/hands-off » et communication avec l'équipe.","s":3},{"q":"Quel est le niveau de preuve des interventions en santé au travail selon Röben et al. (2024) ?","o":["Preuves modérées, aux niveaux individuel, comportemental et organisationnel","Preuves fortes, au seul niveau individuel, sans effet organisationnel","Aucune preuve, à aucun niveau, ni individuel ni organisationnel","Preuves fortes, au seul niveau organisationnel, sans effet individuel"],"r":0,"e":"La mise en œuvre doit reposer sur des interventions fondées sur les preuves.","s":3},{"q":"Quelles sont les 4 phases d'un programme de promotion de la santé au travail ?","o":["Analyse, plan d'intervention, mise en œuvre, évaluation","Diagnostic, traitement médical, suivi régulier, sortie du programme","Recensement, formation, contrôle, sanction","Prévention, dépistage, soin, réadaptation"],"r":0,"e":"La phase 1 correspond à l'identification et au recensement des besoins.","s":3},{"q":"Quel axe figure parmi les programmes de promotion de la santé au travail ?","o":["Le dialogue social et la participation active des partenaires sociaux","La réduction des effectifs pour alléger la masse salariale","L'augmentation des cadences pour améliorer la productivité de l'équipe","La suppression des pauses pour fluidifier le travail"],"r":0,"e":"On retient aussi l'amélioration de l'environnement organisationnel et la promotion du développement personnel.","s":3},{"q":"Quelle prévalence de plaintes cervicales et du membre supérieur présente l'équipe de chirurgie orthopédique du case study ?","o":["60 %","20 %","85 %","35 %"],"r":0,"e":"Ces plaintes ont entraîné 20 jours perdus au cours des 3 derniers mois.","s":3},{"q":"Quel risque pour l'organisation figure dans le case study ?","o":["Annulation d'interventions chirurgicales et perte de productivité","Perte de qualité de vie et de bien-être des chirurgiens au quotidien","Développement de lésions chroniques chez les chirurgiens","Douleur et dysfonctionnement du membre supérieur"],"r":0,"e":"Les trois autres propositions sont des risques pour les chirurgiens eux-mêmes.","s":3},{"q":"Sur quoi doit se fonder le recensement des besoins ?","o":["Sur les preuves et l'information de l'organisation","Sur l'intuition et l'expérience du kinésithérapeute","Sur les seules plaintes verbales des salariés interrogés au hasard dans les couloirs","Sur les résultats financiers de l'organisation"],"r":0,"e":"Les chirurgiens présentent un risque élevé de développer des TMS liés au travail.","s":3},{"q":"La surveillance de la santé au travail relève de la prévention :","o":["Primaire","Secondaire","Tertiaire","Quaternaire"],"r":1,"e":"La promotion de la santé relève, elle, de la prévention primaire. Les deux se complètent, la prévention tertiaire venant ensuite.","s":3},{"q":"La surveillance de la santé est imposée par la législation :","o":["Toujours, dans toute entreprise, quels que soient les risques","Quand les salariés restent exposés malgré les mesures de prévention","Seulement après un accident du travail grave","Seulement sur demande écrite du salarié"],"r":1,"e":"C'est un dispositif de contrôles de santé répétés destinés à repérer les atteintes causées par le travail.","s":3},{"q":"Le niveau MICRO de surveillance, selon Sluiter et al. (2001), correspond :","o":["Au lieu de travail, pour la surveillance active des salariés exposés au risque","Au milieu clinique, pour le diagnostic et le traitement des travailleurs","À l'échelle nationale, pour la politique de prévention","À l'entreprise entière, pour la gestion des risques"],"r":1,"e":"Le niveau MÉSO correspond à la surveillance active sur le lieu de travail, par questionnaires, entretiens, observation et examen objectif.","s":3},{"q":"Le principe directeur de la surveillance est :","o":["De sélectionner les cas les plus graves","De trouver le plus grand nombre de cas possible","De limiter le nombre d'examens","De ne dépister que les salariés volontaires"],"r":1,"e":"Cela suppose des outils sensibles et fondés sur les symptômes : évaluation rapide, évaluations périodiques et évaluation objective en contexte réel de travail.","s":3},{"q":"En contexte professionnel, les symptômes musculo-squelettiques les plus rapportés sont :","o":["L'inconfort et la douleur","La faiblesse et la fatigue","Les paresthésies et les engourdissements nocturnes","La raideur et les craquements"],"r":0,"e":"La douleur entraîne perte de qualité de vie, perte de bien-être et incapacité, avec un impact à la fois sur le travailleur et sur l'organisation.","s":3},{"q":"Selon Skovlund et al. (2020), l'exposition aux facteurs de risque est liée à une moindre capacité de travail au-delà de :","o":["Un huitième de la journée","Un quart de la journée","La moitié de la journée","Les trois quarts de la journée"],"r":1,"e":"Ce résultat vaut indépendamment du niveau d'exigence du travail, ce qui souligne l'importance de la durée d'exposition en elle-même.","s":3},{"q":"L'inconfort est décrit comme :","o":["Une lésion tissulaire, objectivable à l'examen clinique","Une perception subjective liée à la douleur, la fatigue et l'effort","Un diagnostic médical, posé par le médecin du travail après examen","Une incapacité permanente, reconnue par la caisse"],"r":1,"e":"Il peut survenir après l'exposition et disparaître avec le repos, mais il constitue un prédicteur de la douleur — ce que le cours nomme l'effet permanent. Elle est similaire à la sensation ressentie après un exercice physique.","s":3},{"q":"L'inconfort est utilisé comme outcome :","o":["Objectif pour des effets à long terme","Subjectif pour des effets à court terme","Diagnostique","Pronostique uniquement"],"r":1,"e":"Il se traduit par des régions corporelles endolories consécutives à des positions inadéquates et à une exigence physique.","s":3},{"q":"Le protocole SALTSA a pour objectif :","o":["De traiter les TMS du membre supérieur liés au travail en Europe","De repérer tôt et de façon normalisée les TMS du membre supérieur","De définir la liste des maladies professionnelles","D'évaluer la charge mentale des travailleurs"],"r":1,"e":"Il facilite le recueil uniforme de données et utilise le terme « sentinelle », qui renvoie à la prévention du développement des TMS. Ce système s'applique en Europe.","s":3},{"q":"Pour les manœuvres cliniques du protocole SALTSA, les critères privilégiés ont été :","o":["La spécificité et la rapidité","La sensibilité et la reproductibilité","Le coût réduit et la simplicité d'usage","La tolérance du patient pendant le test"],"r":1,"e":"Toutes présentent des critères de diagnostic différentiel et sont accompagnées de photographies, ce qui favorise l'uniformité entre évaluateurs.","s":3},{"q":"Le niveau de sévérité « latent » du protocole SALTSA correspond à :","o":["Des symptômes ne correspondant pas aux critères temporels","Des symptômes conformes aux critères temporels, sans signes","Des symptômes avec des signes cliniques présents à l'examen","Une absence de symptômes et de signes cliniques à l'examen"],"r":0,"e":"Lorsque les critères temporels ne conviennent pas, le groupe de consensus recommande de relever le niveau latent comme une alerte.","s":3},{"q":"Le niveau « symptomatique avec signes cliniques » exige :","o":["Des symptômes seuls, sans aucun signe clinique retrouvé à l'examen","Des symptômes selon les critères temporels et des signes cliniques","Des signes cliniques seuls, sans symptômes rapportés","Un arrêt de travail pour TMS du membre supérieur"],"r":1,"e":"Ce critère temporel est une condition nécessaire pour établir le niveau symptomatique, et ne peut être remplacé par le critère portant sur les 12 derniers mois. Critère temporel : actuellement ou au moins 4 jours dans la dernière semaine.","s":3},{"q":"Le second critère temporel SALTSA porte sur des symptômes présents :","o":["Pendant 4 jours en une semaine au cours des 12 derniers mois","Pendant un mois continu, au cours des 12 derniers mois","Depuis plus de 6 mois, sans interruption","Depuis la prise de poste, quelle que soit leur durée"],"r":0,"e":"Au moins l'un des deux critères temporels doit être présent pour définir un cas symptomatique.","s":3},{"q":"L'évaluation de la capacité fonctionnelle pour le travail est de préférence :","o":["Réalisée par le seul médecin du travail, en consultation","Multidisciplinaire, avec médecine du travail, kiné et psychologie si besoin","Confiée à l'employeur, sur la base d'un entretien annuel","Auto-administrée par le salarié, par questionnaire en ligne et sans aucun entretien"],"r":1,"e":"Elle se combine à l'analyse individuelle de la situation de travail et considère fonction et structure corporelles, facteurs environnementaux et personnels, et état de santé.","s":3},{"q":"Parmi les fonctions évaluées dans la capacité fonctionnelle figure :","o":["La force dynamique : soulever, porter, tirer, pousser","La mémoire de travail : retenir, rappeler, organiser","La vision des couleurs : distinguer, nommer, comparer","L'audition : entendre, localiser, comprendre une consigne dans le bruit du poste"],"r":0,"e":"S'y ajoutent la capacité de déplacement au poste, la mobilité, l'équilibre, la latéralité, la coordination motrice fine et l'endurance sur la journée.","s":3},{"q":"Le Work Ability Index se détermine selon :","o":["L'ancienneté du salarié dans l'entreprise","L'état de santé du travailleur et ses ressources","Le seul avis du médecin du travail","La productivité mesurée sur l'année écoulée"],"r":1,"e":"Selon Ilmarinen, la capacité de travail est une dimension continue, de la pleine capacité à l'incapacité totale.","s":3},{"q":"Selon Tegland (2011), la capacité de travail est d'autant plus élevée que :","o":["Le salaire, les primes et les avantages en nature sont importants","La compétence, la santé, la flexibilité, l'adaptation sont grandes","L'âge, l'ancienneté et la charge de travail du salarié sont faibles","Les horaires, les trajets et les pauses sont courts"],"r":1,"e":"Cette conception dépasse la seule aptitude physique : elle intègre les ressources adaptatives de la personne. Les vertus professionnelles comptent aussi.","s":3},{"q":"Le Nordic Musculoskeletal Questionnaire évalue les symptômes sur :","o":["Les 30 derniers jours et les 24 dernières heures","Les 12 derniers mois et/ou les 7 derniers jours","La dernière semaine uniquement, jour par jour","Toute la carrière, depuis le premier emploi et chaque poste occupé"],"r":1,"e":"Il recherche courbatures, douleurs, gêne ou engourdissement. Il a été décrit par Kuorinka et ses collaborateurs en 1994.","s":3},{"q":"Le Job Content Questionnaire de Karasek comporte :","o":["3 sous-échelles","5 sous-échelles","7 sous-échelles","10 sous-échelles"],"r":1,"e":"Exigences psychologiques, latitude décisionnelle, soutien social, exigences physiques et insécurité au travail. Sa version française est due à Brisson et ses collaborateurs en 1998.","s":3},{"q":"Le modèle d'exposition physique du membre supérieur distal repose sur :","o":["Intensité, fréquence et durée de l'effort, posture, durée quotidienne","La seule intensité de l'effort, mesurée en newtons au dynamomètre de poignet","L'âge et l'ancienneté du travailleur dans le poste","La charge mentale et le stress perçu au poste"],"r":0,"e":"Ces cinq paramètres se combinent : une posture acceptable devient délétère si la fréquence et la durée quotidienne sont élevées. La posture concerne la main et le poignet.","s":3},{"q":"Quels sont les 4 niveaux du modèle d'évaluation de l'épaule ?","o":["Base musculo-squelettique, modulation nerveuse, biomécanique, support","Structure, fonction, activité et participation, selon la classification de l'OMS","Douleur, force, mobilité et endurance de l'épaule","Statique, dynamique, fonctionnel et sportif"],"r":0,"e":"La biomécanique recouvre l'équilibre musculaire et la stabilité dynamique.","s":4},{"q":"Quel red flag évoque une pathologie viscérale à l'épaule ?","o":["Douleur scapulaire après un repas gras, avec troubles digestifs","Perte de poids soudaine, fatigue inexpliquée et sueurs nocturnes","Zone rougie, chaude et fébrile, avec malaise général","Déficit moteur sans explication, avec paresthésies"],"r":0,"e":"La perte de poids évoque une néoplasie, la rougeur fébrile une infection.","s":4},{"q":"Quel red flag évoque une infection ?","o":["Zone rougie, fébrile et malaise systématique","Traumatisme significatif avec déformation de l'épaule","Perte de poids soudaine, fatigue inexpliquée","Douleur non reproduite mécaniquement, au repos"],"r":0,"e":"La déformation après traumatisme évoque une fracture ou une luxation non réduite.","s":4},{"q":"Quelle atteinte du rachis cervical peut simuler une douleur d'épaule ?","o":["Une radiculopathie C5-C6","Une radiculopathie C8-T1","Une arthrose C1-C2","Une hernie discale C7-T1"],"r":0,"e":"On retient aussi la douleur référée cervicale et la dysfonction cervico-thoracique.","s":4},{"q":"Quel muscle voit son activation augmenter en cas de douleur d'épaule ?","o":["Le trapèze supérieur","Le grand dentelé","Le trapèze inférieur","Le subscapulaire"],"r":0,"e":"L'activation du grand dentelé et du trapèze inférieur est au contraire réduite.","s":4},{"q":"Que compromet l'altération du rythme scapulo-huméral ?","o":["La position de la tête humérale dans la glène","La mobilité du coude et de l'avant-bras en prono-supination","La force de préhension de la main","La stabilité lombaire et pelvienne"],"r":0,"e":"La coordination entre scapulo-thoracique et gléno-humérale est cruciale.","s":4},{"q":"Comment faut-il comprendre la zone neutre scapulo-thoracique ?","o":["Une zone de variabilité acceptable, selon la tâche et le contexte","Une position fixe, à maintenir en permanence pendant chaque mouvement du bras","Un objectif final de rééducation, à atteindre en fin de prise en charge","Un test diagnostique de dyskinésie scapulaire"],"r":0,"e":"Son entraînement est surtout une stratégie initiale de rééducation neuromusculaire.","s":4},{"q":"À quel niveau vertébral se situe l'angle supérieur de la scapula ?","o":["T2-T3","T3-T4","T7-T9","T1"],"r":0,"e":"L'épine s'aligne sur T3-T4 et l'angle inférieur se situe entre T7 et T9.","s":4},{"q":"Où se situe l'angle inférieur de la scapula ?","o":["Entre T7 et T9","Entre T2 et T3","Entre T3 et T4","En regard de T12"],"r":0,"e":"Cette valeur varie selon la morphologie et la posture.","s":4},{"q":"Quelle est la distance de référence entre le bord médial de la scapula et le rachis ?","o":["5-7 cm","1,5 cm","10-12 cm","2-3 cm"],"r":0,"e":"Elle indique l'absence de protraction ou de rétraction excessive.","s":4},{"q":"Quelle est l'orientation de repos de la scapula ?","o":["30-40° de rotation interne, 10-20° d'inclinaison antérieure","10° de rotation interne, 50° d'inclinaison antérieure","30° de rotation externe, 10-20° d'inclinaison postérieure","0° de rotation, 0° d'inclinaison, scapula parfaitement plaquée au gril costal"],"r":0,"e":"La rotation externe est minimale au repos.","s":4},{"q":"Que mesure le Lateral Scapula Slide Test ?","o":["La distance entre l'angle inférieur de la scapula et l'épineuse en regard","La distance entre l'acromion et le rachis cervical, mesurée en centimètres au mètre ruban","L'angle d'inclinaison antérieure de la scapula au repos","La force du grand dentelé contre résistance"],"r":0,"e":"Il se réalise dans 3 positions de test (Kibler, 1998).","s":4},{"q":"À partir de quelle asymétrie le LSST est-il positif ?","o":["1,5 cm","0,5 cm","3 cm","5 cm"],"r":0,"e":"Des différences constantes dans plus d'une position augmentent la probabilité de dyskinésie scapulaire.","s":4},{"q":"Quelle est la principale limite du LSST ?","o":["Il ne voit que la position statique, pas les altérations dynamiques","Il est trop long à réaliser en consultation","Il nécessite un appareillage coûteux, comme un inclinomètre électronique ou un capteur","Il est douloureux chez le patient opéré"],"r":0,"e":"Sa fiabilité inter-évaluateurs est modérée et sa sensibilité/spécificité limitées.","s":4},{"q":"Que signifie « proximal stability for distal mobility » ?","o":["La stabilité proximale conditionne la mobilité distale","La mobilité distale précède et conditionne la stabilité proximale","Il faut mobiliser avant de stabiliser","La scapula doit rester fixe pendant le mouvement"],"r":0,"e":"On évalue l'alignement lombo-pelvien neutre et la stabilité cervicale. Le contrôle postural global en fait partie.","s":4},{"q":"Combien de temps maintient-on activement les positions du PNF de la scapula ?","o":["15 secondes","3 secondes","1 minute","30 secondes"],"r":0,"e":"Les schémas sont d'abord réalisés passivement, patient en décubitus latéral.","s":4},{"q":"Quel schéma correspond au 1A du PNF scapulaire ?","o":["Abaissement/adduction","Élévation/abduction","Abaissement/abduction","Élévation/adduction"],"r":0,"e":"1B = élévation/abduction, 2A = abaissement/abduction, 2B = élévation/adduction.","s":4},{"q":"Comment se présente une atteinte de l'articulation acromio-claviculaire ?","o":["Douleur en fin d'adduction horizontale, bien localisée, montrée du doigt","Douleur à la base antérieure du cou, en flexion cervicale contrariée","Douleur diffuse au repos, mal localisée","Douleur irradiée au coude, sur la face latérale"],"r":0,"e":"Les tests sont l'adduction horizontale après flexion à 90° et le Shear Test.","s":4},{"q":"Quel est le traitement manuel de la sterno-claviculaire ?","o":["Mouvement rythmé des deux mains dans l'axe de la clavicule, côté interne","Traction dans l'axe de la clavicule, pression thénar sur l'extrémité externe","Compression axiale de l'humérus vers la glène, coude fléchi","Mobilisation de la scapula en sonnette, main sur l'angle inférieur et l'autre sur l'acromion"],"r":0,"e":"Pour l'acromio-claviculaire, on réalise une traction dans l'axe avec pression thénar sur l'extrémité externe. La main céphalique est sur l'extrémité interne.","s":4},{"q":"Quelle amplitude définit la phase 2 du rythme scapulo-huméral ?","o":["De 30 à 90° d'abduction","De 0 à 30° d'abduction","De 90 à 150° d'abduction","De 150 à 180° d'abduction, en fin de course"],"r":0,"e":"La scapula réalise alors une rotation supérieure d'environ 20°.","s":4},{"q":"Quelle est l'élévation claviculaire en phase 1 du rythme scapulo-huméral ?","o":["0 à 5° dans la sterno-claviculaire","Environ 15° dans la sterno-claviculaire","Environ 30° dans la sterno-claviculaire","Environ 50° dans la sterno-claviculaire et l'acromio-claviculaire"],"r":0,"e":"En phase 2, elle progresse jusqu'à environ 15°.","s":4},{"q":"Que se passe-t-il à la clavicule en phase 3 ?","o":["Environ 15° d'élévation en plus, et 30-50° de rotation postérieure","0 à 5° d'élévation seulement, sans rotation de la clavicule, comme en phase 1","Aucun mouvement, la clavicule étant bloquée","50° de rotation antérieure, sans élévation"],"r":0,"e":"La mobilité fonctionnelle de l'acromio-claviculaire y est essentielle.","s":4},{"q":"Pourquoi la rotation externe gléno-humérale est-elle nécessaire en phase 3 ?","o":["Pour éviter le conflit sous-acromial","Pour augmenter la force","Pour stabiliser la clavicule","Pour limiter la rotation scapulaire"],"r":0,"e":"La phase 3 couvre 90-150° d'abduction avec environ 90° de rotation externe.","s":4},{"q":"Entre quels degrés se situe l'arc douloureux ?","o":["Entre 60° et 120° d'abduction","Entre 0° et 30° d'abduction, en début de mouvement","Entre 120° et 180° d'abduction","Entre 30° et 60° d'abduction"],"r":0,"e":"Il peut indiquer un syndrome de conflit sous-acromial (Dhillon, 2019).","s":4},{"q":"Comment installe-t-on le test de la position neutre gléno-humérale ?","o":["DD, humérus à 90° d'abduction dans le plan scapulaire, coude à 90°, 15 s","DB, bras le long du corps, coude tendu, 15 s","DV, bras pendant hors de la table, coude tendu, 15 s","Assis, coude en extension, épaule à 30° d'abduction, maintien de 15 s, puis relâchement"],"r":0,"e":"On demande ensuite de changer de position puis de la reprendre. DD : décubitus dorsal ; DB : debout ; DV : décubitus ventral.","s":4},{"q":"Que définit la réactivité d'un test ?","o":["La détection de changements réels et cliniquement pertinents dans le temps","La cohérence des résultats répétés, entre évaluateurs et entre séances successives","La capacité à identifier les vrais positifs","La mesure du phénomène qu'il prétend évaluer"],"r":0,"e":"La fiabilité concerne la reproductibilité, la sensibilité les vrais positifs, la validité le phénomène mesuré.","s":4},{"q":"Quelle est la procédure du test de Hawkins-Kennedy ?","o":["Épaule et coude à 90° avec rotation interne passive","Flexion passive avec rotation interne","Main sur l'épaule controlatérale avec élévation du coude","Abduction 90° et rotation externe"],"r":0,"e":"Il explore le supra-épineux et le ligament coraco-acromial ; il est positif en cas de douleur sous-acromiale.","s":4},{"q":"Que suggèrent un Empty Can et un Full Can tous deux faibles ?","o":["Une rupture de la coiffe","Une tendinopathie isolée du supra-épineux","Un conflit sous-acromial","Une instabilité antérieure"],"r":0,"e":"Une douleur au Full Can associée à un Empty Can douloureux oriente vers une tendinopathie.","s":4},{"q":"Quel test explore le subscapulaire ?","o":["Le Lift Off Test de Gerber","L'External Rotation Lag Sign","Le Drop Arm","Le test de Speed"],"r":0,"e":"L'External Rotation Lag Sign explore l'infra-épineux.","s":4},{"q":"À quelle pression gonfle-t-on le biofeedback lors du test de low load recruitment ?","o":["20 mmHg","6 mmHg","40 mmHg","100 mmHg"],"r":0,"e":"Une réduction à 6-10 mmHg, une activation excessive des scalènes ou une fatigue précoce sont des signes anormaux.","s":4},{"q":"L'angle supérieur de la scapula se situe normalement en regard de :","o":["T1","T2-T3","T3-T4","T7-T9"],"r":1,"e":"L'épine s'aligne sur T3-T4 et l'angle inférieur se situe entre T7 et T9. Le bord médial se tient à 5 à 7 cm du rachis.","s":4},{"q":"L'orientation normale de la scapula comporte :","o":["30 à 40° de rotation interne, 10 à 20° d'inclinaison antérieure","10° de rotation interne, 30° d'inclinaison antérieure","45° de rotation externe, 10 à 20° d'inclinaison postérieure","0° de rotation, aucune inclinaison, scapula parfaitement verticale et plaquée"],"r":0,"e":"Ces repères définissent la position de référence à partir de laquelle toute asymétrie est appréciée.","s":4},{"q":"Le Lateral Scapula Slide Test de Kibler (1998) comporte :","o":["2 positions","3 positions","4 positions","5 positions"],"r":1,"e":"Il est considéré comme positif si l'asymétrie atteint ou dépasse 1,5 cm.","s":4},{"q":"Les limites du Lateral Scapula Slide Test sont :","o":["Une fiabilité modérée entre évaluateurs et une mesure seulement statique","Une durée excessive et un matériel encombrant","Un coût élevé et une formation longue, qui en limitent beaucoup l'usage en cabinet","Une contre-indication en cas de douleur ou d'instabilité"],"r":0,"e":"Il ne renseigne donc pas sur la qualité du mouvement, ce qui impose de le compléter par l'observation dynamique du rythme scapulo-huméral.","s":4},{"q":"Dans la phase 1 du rythme scapulo-huméral, de 0 à 30° :","o":["Un mouvement scapulaire minimal, une clavicule qui s'élève de 0 à 5°","Une rotation supérieure de 20°, une clavicule qui s'élève de 15°","Une clavicule qui s'élève de 15°, sans aucun mouvement de la scapula","Une rotation postérieure de 50°, une rotation supérieure de 30°, une clavicule qui s'élève"],"r":0,"e":"C'est la phase de mise en tension, où l'humérus se déplace pour l'essentiel dans la glène.","s":4},{"q":"Dans la phase 2 du rythme scapulo-huméral, de 30 à 90° :","o":["Un mouvement scapulaire minimal, une clavicule qui s'élève de 0 à 5°","Une rotation supérieure d'environ 20°, une clavicule qui s'élève d'environ 15°","Une rotation postérieure de la clavicule d'environ 50°, avec 30° de rotation supérieure","Aucun mouvement de la clavicule, une scapula qui reste fixe"],"r":1,"e":"La phase 3, de 90 à 150°, ajoute environ 30° de rotation supérieure, 15° d'élévation claviculaire et 30 à 50° de rotation postérieure.","s":4},{"q":"Un arc douloureux situé entre 60 et 120° d'abduction évoque :","o":["Une capsulite rétractile","Un conflit sous-acromial","Une instabilité antérieure","Une atteinte acromio-claviculaire"],"r":1,"e":"C'est dans cette fenêtre que l'espace sous-acromial se réduit le plus, comprimant bourse et tendon de la coiffe.","s":4},{"q":"La douleur et la dysfonction de l'épaule modifient l'activation musculaire en :","o":["En augmentant l'activation du grand dentelé et celle du trapèze inférieur, sans toucher au supérieur","En réduisant le grand dentelé et le trapèze inférieur, en augmentant le trapèze supérieur","En réduisant toutes les activations, de façon diffuse et symétrique","En augmentant le trapèze inférieur, en réduisant le trapèze supérieur"],"r":1,"e":"Ce déséquilibre compromet la rotation supérieure de la scapula, donc aggrave le conflit — un cercle vicieux classique.","s":4},{"q":"Le test de low load recruitment utilise un biofeedback gonflé à :","o":["10 mmHg","20 mmHg","40 mmHg","60 mmHg"],"r":1,"e":"Il se réalise avec un chin tuck. Le test est anormal en cas de réduction à 6-10 mmHg, d'activation excessive des scalènes, de rigidité mandibulaire ou de fatigue précoce.","s":4},{"q":"Dans le cadre de l'évaluation de l'épaule, le niveau « MODULATION » correspond :","o":["Au système musculo-squelettique","Au système nerveux","À l'équilibre musculaire","Aux autres systèmes"],"r":1,"e":"Le système musculo-squelettique constitue la BASE, l'équilibre musculaire et la stabilité dynamique la BIOMÉCANIQUE, les autres systèmes le SUPPORT.","s":4},{"q":"Selon le modèle adapté de Hall et Brody (1999), les objectifs d'intervention doivent être :","o":["Clairs, quantifiables, motivants, réalisables, avec des délais","Ambitieux, généraux, sans délai, laissés à la libre appréciation du patient","Fixés par le médecin, sans adaptation, non négociables","Identiques pour tous les patients, quelle que soit leur épaule"],"r":0,"e":"On y reconnaît la structure des objectifs SMART, transposée au contexte spécifique de la rééducation de l'épaule. Ils sont aussi alignés sur les ressources disponibles.","s":4},{"q":"L'examen subjectif de l'épaule suit trois axes :","o":["Histoire clinique, caractérisation de la douleur, comportement des symptômes","Douleur, force et amplitude, mesurées au goniomètre et au dynamomètre","Observation, palpation et testing de la coiffe","Antécédents, imagerie et traitement en cours"],"r":0,"e":"Cette structure reprend celle du raisonnement clinique général, appliquée aux spécificités du complexe de l'épaule. L'histoire est actuelle et antérieure ; la douleur est caractérisée et localisée.","s":4},{"q":"Parmi les hypothèses d'origine cervicale dans le diagnostic différentiel de l'épaule figure :","o":["La bursite sous-acromiale, avec un arc douloureux","La radiculopathie C5-C6, avec dysfonction cervico-thoracique","La tendinopathie C5 du supra-épineux, en abduction","L'épicondylalgie latérale, avec douleur référée en C6-C7"],"r":1,"e":"L'épaule est une région où la douleur référée est fréquente : le rachis cervical et le coude doivent être systématiquement dépistés.","s":4},{"q":"Parmi les atteintes du tissu neural évoquées figure :","o":["La neuropathie du nerf supra-scapulaire","La capsulite rétractile de l'épaule","La synovite gléno-humérale inflammatoire","L'arthrose acromio-claviculaire évoluée"],"r":0,"e":"S'y ajoutent l'atteinte du plexus brachial et la sensibilisation neurale périphérique ou centrale.","s":4},{"q":"L'examen objectif de l'épaule comprend, au titre de la qualité du mouvement :","o":["La force analytique de chaque muscle","Le rythme scapulo-huméral et le contrôle moteur scapulaire","La palpation des structures douloureuses","Les échelles fonctionnelles remplies par le patient en salle d'attente"],"r":1,"e":"S'y ajoutent l'amplitude active et passive, la mobilité articulaire avec l'end-feel, la force, l'endurance et les tests spécifiques.","s":4},{"q":"Parmi les antécédents cliniques à explorer, le cours cite :","o":["Conflit sous-acromial, lésion du bourrelet, défilé, hypermobilité, capsulite","Traumatismes seuls, comme une luxation, une fracture ou une rupture de coiffe","Conditions dégénératives seules, comme l'arthrose ou la rupture d'usure","Néoplasies seules, comme une métastase, un myélome ou une tumeur de Pancoast"],"r":0,"e":"Les trois grandes catégories initiales sont le traumatisme, les conditions dégénératives et les conditions inflammatoires. La lésion du bourrelet correspond à la lésion SLAP ; les calcifications en font aussi partie.","s":4},{"q":"Le schéma respiratoire fait partie de l'examen objectif de l'épaule parce que :","o":["Il n'a aucun lien avec l'épaule, mais il fait partie du bilan général","La mécanique thoracique conditionne la position de la scapula","Il permet de mesurer l'effort fourni pendant les tests","Il évalue la douleur ressentie à l'inspiration profonde, en fin d'amplitude"],"r":1,"e":"Un schéma costal supérieur sur-sollicite les muscles accessoires du cou, dont le trapèze supérieur, déjà hyperactif en cas de dysfonction d'épaule. Elle conditionne aussi le fonctionnement de toute la ceinture scapulaire.","s":4},{"q":"Le bord médial de la scapula se situe normalement à :","o":["2-3 cm du rachis","5-7 cm du rachis","10-12 cm du rachis","Au contact du rachis"],"r":1,"e":"Cette distance, comme les repères vertébraux, permet d'objectiver une bascule ou un décollement plutôt que de s'en remettre à une impression visuelle.","s":4},{"q":"En phase 3 du rythme scapulo-huméral, la rotation postérieure de la clavicule atteint :","o":["5 à 10°","15 à 20°","30 à 50°","60 à 70°"],"r":2,"e":"Sans cette rotation postérieure, l'élévation complète du bras est impossible — ce qui explique son importance dans le rythme scapulo-huméral.","s":4},{"q":"Un test de low load recruitment révélant une activation excessive des scalènes traduit :","o":["Un bon recrutement des fléchisseurs profonds du cou, sans compensation","Une compensation par les fléchisseurs superficiels du cou","Une hypermobilité du rachis cervical haut","Une fatigue normale en fin de série"],"r":1,"e":"L'objectif du chin tuck est de solliciter les fléchisseurs profonds ; le recours aux scalènes signale que la stratégie profonde fait défaut.","s":4},{"q":"Quels éléments recueille-t-on à l'examen subjectif lombaire ?","o":["Douleur, sommeil, profession, traitement et examens complémentaires","Douleur seule, son intensité et sa localisation","Imagerie seule, radiographie et IRM du rachis","Profession seule, avec les postures et les charges portées au travail"],"r":0,"e":"L'examen objectif suit un raisonnement clinique : hypothèses, tests, traitement, réévaluation. Pour la douleur : son début et son comportement.","s":5},{"q":"Que signifie SIN dans la caractérisation de la douleur ?","o":["Sévérité, irritabilité, nature","Siège, intensité, névralgie","Spontané, insidieux, nocturne","Symptôme, intensité, nuit"],"r":0,"e":"On précise aussi si le début est soudain ou insidieux.","s":5},{"q":"Quel repère postural concerne l'oreille ?","o":["Le lobe de l'oreille derrière la clavicule","Le lobe de l'oreille aligné avec l'épaule","Le lobe de l'oreille en avant du sternum, sur la ligne médiane","Le tragus aligné avec la malléole"],"r":0,"e":"On vérifie aussi que le grand trochanter est aligné avec la malléole externe.","s":5},{"q":"Que doit faire la grille costale à l'inspiration ?","o":["S'ouvrir latéralement","Se fermer","Monter en bloc","Rester immobile"],"r":0,"e":"À l'expiration, elle se relâche.","s":5},{"q":"Que traduit une saillie de l'abdomen lors des tests ?","o":["Une stabilité insuffisante","Une force excessive du transverse","Une bonne proprioception","Un raccourcissement du psoas"],"r":0,"e":"Rotation du bassin, inclinaison du tronc et saillie thoracique traduisent une faiblesse du transverse et/ou du plancher pelvien.","s":5},{"q":"Comment palpe-t-on le transverse de l'abdomen ?","o":["En faisant tousser ou rire le patient","En lui demandant de fléchir le tronc","À 2-3 cm en dedans de l'EIAS","Latéralement au rachis"],"r":0,"e":"Les obliques se palpent à 2-3 cm en dedans de l'EIAS.","s":5},{"q":"Où palpe-t-on les multifides ?","o":["Latéralement au rachis, en direction de la vertèbre inférieure","À 2-3 cm en dedans de l'EIAS, en direction du pubis et de la symphyse","Sur la crête iliaque, en arrière","Sous le rebord costal, en dehors"],"r":0,"e":"Ils font partie des stabilisateurs locaux avec le diaphragme, le transverse et le plancher pelvien.","s":5},{"q":"Où se palpent les obliques interne et externe ?","o":["À 2-3 cm en dedans de l'EIAS","À 2-3 cm de l'ombilic","À 2-3 cm en dehors des EIPS","À 2-3 cm au-dessus du pubis"],"r":0,"e":"Ce sont des stabilisateurs globaux ; la contraction doit être distincte.","s":5},{"q":"Quels tests de contrôle dynamique réalise-t-on en décubitus ventral ?","o":["Flexion du genou et extension de la hanche","SLR actif et flexion de hanche","Squat et appui unipodal","Flexion de hanche bilatérale et extension unilatérale"],"r":0,"e":"Le SLR actif se réalise en décubitus dorsal. Le SLR actif se fait sur le dos, le squat debout, la flexion de hanche bilatérale à quatre pattes.","s":5},{"q":"Quel test de contrôle dynamique réalise-t-on debout ?","o":["Le pas, l'appui unipodal et le squat","Le SLR actif, jambe tendue, en décubitus","La flexion du genou, en décubitus ventral","L'alignement du dos, à quatre pattes"],"r":0,"e":"À quatre pattes, on teste l'alignement, la flexion de hanche bilatérale et l'extension unilatérale.","s":5},{"q":"Qui a développé le test de proprioception lombo-pelvienne cité ?","o":["Maffey-Ward et al. (1996)","Kibler et al. (1998)","Panjabi et al. (1992)","Souchard et al. (1980)"],"r":0,"e":"Le résultat se cote bon, moyen ou faible.","s":5},{"q":"Comment cote-t-on « moyen » au test de proprioception ?","o":["Il retrouve la position neutre, mais se montre incertain","Il retrouve la position neutre et se montre confiant","Il ne parvient pas à retrouver la position neutre","Il refuse le test, par peur de la douleur"],"r":0,"e":"« Bon » = retrouvée avec confiance ; « faible » = non retrouvée.","s":5},{"q":"Comment mesure-t-on la longueur des membres inférieurs ?","o":["Nombril – malléole interne, puis EIAS – malléole interne, sur le dos","Crête iliaque – malléole externe, debout, pieds joints et genoux tendus","Grand trochanter – interligne du genou, debout","EIPS – talon, en décubitus ventral"],"r":0,"e":"Pour les tests dynamiques d'ouverture/fermeture, on vérifie le bord inférieur des malléoles tibiales.","s":5},{"q":"Que conclut-on d'une manœuvre de Valsalva positive ?","o":["Une protrusion discale ou une compression radiculaire","Une dysfonction sacro-iliaque bloquée du même côté que la douleur","Un raccourcissement du psoas, avec hyperlordose","Une faiblesse du moyen fessier"],"r":0,"e":"Le test est réalisé assis, avec apnée et poussée expulsive des abdominaux.","s":5},{"q":"Quelle amplitude de flexion de hanche caractérise le test de Lasègue ?","o":["30 à 70°","0 à 30°","70 à 90°","90 à 120°"],"r":0,"e":"Le genou est en extension maximale ; le test explore les racines L4-S1.","s":5},{"q":"Quand réalise-t-on le test de Bragard ?","o":["Après un SLR positif","Avant le SLR, d'emblée","Debout, avant le SLR","En DV, après le SLR"],"r":0,"e":"On ajoute une flexion dorsale de la tibio-tarsienne, légèrement en deçà du SLR douloureux. DV : décubitus ventral.","s":5},{"q":"Que permet de confirmer le test de Bragard ?","o":["Une atteinte radiculaire, et non des ischio-jambiers courts","Un raccourcissement des ischio-jambiers, et non une racine","Une dysfonction sacro-iliaque, et non une atteinte radiculaire","Une bursite trochantérienne, et non une sciatique"],"r":0,"e":"Il se réalise après un SLR positif.","s":5},{"q":"Quelles marques utilise le test de Schober ?","o":["Le point médian entre les 2 EIPS et une marque 10 cm au-dessus","Le point médian entre les 2 EIPS et une marque 5 cm au-dessous","L'EIAS et la malléole interne, de chaque côté, en décubitus","C7 et S1, en position debout, puis en flexion"],"r":0,"e":"La distance doit augmenter de 5 cm lors de la flexion du tronc.","s":5},{"q":"Quelles valeurs de Schober sont considérées comme pathologiques ?","o":["Plus de 8 cm ou moins de 3 cm","Moins de 5 cm ou plus de 6 cm","Exactement 5 cm","Plus de 5 cm"],"r":0,"e":"Cela traduit une hypermobilité ou une hypomobilité.","s":5},{"q":"Quelles racines explore le Femoral Nerve Stretch Test ?","o":["L2-L4","L4-S1","C5-C6","S2-S4"],"r":0,"e":"Il se réalise en décubitus ventral ou latéral, par flexion du genou avec hyperextension de hanche.","s":5},{"q":"Que conclut-on d'un signe de Piedallu positif en position assise ?","o":["Un blocage du sacrum par rapport à l'iliaque","Une restriction de l'iliaque par rapport au sacrum","Une hernie discale L5-S1","Une faiblesse du moyen fessier, du côté de l'appui"],"r":0,"e":"En position debout, il traduit une restriction de l'iliaque.","s":5},{"q":"Que traduit un Gillet Test positif ?","o":["Une dysfonction de la sacro-iliaque du même côté","Une hernie discale L5-S1 du même côté","Un raccourcissement du droit fémoral controlatéral","Une bursite du psoas, à la face antérieure de la hanche"],"r":0,"e":"Le test est positif si l'EIPS ne se déplace pas vers le bas et vers le dedans par rapport à S2.","s":5},{"q":"Comment réalise-t-on le Gaenslen's Test ?","o":["Sur le dos, un membre fléchi, l'autre hors de la table, extension forcée","Debout, en appui unipodal, flexion de hanche et de genou contre résistance","Sur le ventre, flexion du genou maximale","Assis, flexion du tronc vers l'avant, jambes tendues"],"r":0,"e":"Il est positif en cas de douleur SI, à la symphyse pubienne ou à la hanche.","s":5},{"q":"Quel mouvement compose le test de Faber ?","o":["Flexion, abduction et rotation externe de hanche","Flexion, adduction et rotation interne de hanche","Extension, abduction et rotation interne de hanche","Extension, adduction et rotation externe de hanche"],"r":0,"e":"Le test de Fadir associe flexion, adduction et rotation interne.","s":5},{"q":"Que dépiste le test de Fadir ?","o":["Une pathologie sacro-iliaque ou un conflit fémoro-acétabulaire","Un raccourcissement du psoas ou du droit fémoral","Une radiculopathie L2-L4 ou une cruralgie, avec déficit du quadriceps","Une faiblesse du transverse ou des obliques"],"r":0,"e":"Il associe flexion, adduction et rotation interne de hanche.","s":5},{"q":"Que conclut-on d'un signe de la fesse positif ?","o":["Une pathologie de la hanche ou de la fesse","Une hernie discale L5-S1 avec sciatique","Une dysfonction sacro-iliaque bloquée","Un raccourcissement des ischio-jambiers"],"r":0,"e":"Il se recherche après un SLR limité, en fléchissant le genou. Par exemple une bursite, un abcès ou une néoplasie.","s":5},{"q":"Que révèle un Thomas Test positif ?","o":["Un raccourcissement des fléchisseurs de hanche","Un raccourcissement du droit fémoral seul","Une faiblesse du moyen fessier","Une dysfonction SI"],"r":0,"e":"Le test est positif si le genou se soulève.","s":5},{"q":"Que révèle un test d'Ely positif ?","o":["Un raccourcissement du droit fémoral","Un raccourcissement de l'ilio-psoas","Une atteinte radiculaire L2-L4","Une bursite fessière profonde"],"r":0,"e":"Il se réalise en décubitus ventral par flexion maximale du genou. Le droit fémoral est aussi appelé droit antérieur.","s":5},{"q":"Que traduit un signe de Trendelenburg positif ?","o":["Une faiblesse du moyen fessier du côté en charge","Une faiblesse du moyen fessier du côté non appuyé","Un raccourcissement du psoas du côté en charge","Une dysfonction de la symphyse pubienne"],"r":0,"e":"Il se recherche debout en appui unipodal ; le bassin chute du côté non appuyé.","s":5},{"q":"Quelle bourse donne une douleur assise qui disparaît debout ?","o":["La bourse des ischio-jambiers","La bourse du psoas","La bourse fessière","La bourse trochantérienne"],"r":0,"e":"La bourse du psoas donne une douleur à l'aine en flexion et adduction.","s":5},{"q":"Le test de Schober se réalise en marquant :","o":["Deux points distants de 5 cm sur le rachis, à partir de la vertèbre L5","Le point médian entre les deux EIPS et une marque 10 cm au-dessus","Trois points sur le rachis, à 10 cm d'écart","Les deux EIAS, de part et d'autre"],"r":1,"e":"La distance doit augmenter de 5 cm en flexion ; au-delà de 8 cm ou en deçà de 3 cm, le résultat est considéré comme pathologique.","s":5},{"q":"Le test de Lasègue se réalise entre :","o":["Entre 0 et 30° de flexion de hanche","Entre 30 et 70° de flexion de hanche","Entre 70 et 90° de flexion de hanche","Entre 90 et 120° de flexion de hanche"],"r":1,"e":"Il explore les racines L4-S1. En dehors de cette fenêtre angulaire, la reproduction des symptômes oriente vers d'autres causes. Le genou reste en extension.","s":5},{"q":"Le test de Bragard, réalisé après un Lasègue positif, sert à :","o":["Mesurer l'amplitude de la flexion de hanche","Confirmer l'atteinte radiculaire, plutôt que des ischio-jambiers courts","Tester la sacro-iliaque en tension, sous le même angle de flexion de hanche","Évaluer la force des fléchisseurs dorsaux de la cheville"],"r":1,"e":"Il consiste à ajouter une flexion dorsale de cheville à l'angle où le Lasègue devient positif, ce qui met le nerf en tension sans allonger davantage les ischio-jambiers.","s":5},{"q":"Le test de Piedallu réalisé en position assise explore :","o":["Une restriction du sacrum","Une restriction de l'iliaque","La sacro-iliaque controlatérale","Le rachis lombaire"],"r":0,"e":"Le Piedallu debout explore, lui, une restriction de l'iliaque. La position modifie la contrainte et permet de différencier les deux.","s":5},{"q":"Le test de Gillet met en évidence :","o":["Une dysfonction de la sacro-iliaque du même côté","Une atteinte radiculaire du même côté, avec déficit sensitif","Une protrusion discale L4-L5","Un raccourcissement musculaire"],"r":0,"e":"Il s'inscrit avec les tests de Piedallu dans l'exploration du complexe sacro-iliaque.","s":5},{"q":"Le Femoral Nerve Stretch Test oriente vers :","o":["Une atteinte radiculaire L4-S1","Une radiculopathie ou une protrusion L2-L4","Une dysfonction sacro-iliaque, du même côté","Un syndrome facettaire lombaire"],"r":1,"e":"Il complète le Lasègue, qui explore les racines basses : les deux tests couvrent ensemble l'ensemble du plexus lombo-sacré.","s":5},{"q":"La manœuvre de Valsalva se réalise :","o":["En décubitus dorsal, jambe tendue","Assis, avec apnée et poussée abdominale","Debout, en flexion du tronc","En procubitus, jambes tendues et bras le long du corps"],"r":1,"e":"L'apparition ou l'augmentation de la douleur oriente vers une protrusion discale ou une compression radiculaire, par élévation de la pression intrarachidienne.","s":5},{"q":"Le transverse de l'abdomen se palpe en demandant au patient :","o":["De tousser ou de rire","De retenir sa respiration","De soulever les jambes","De se pencher en avant"],"r":0,"e":"Ces manœuvres provoquent une contraction réflexe du transverse, plus facile à percevoir qu'une contraction volontaire souvent mal exécutée.","s":5},{"q":"Les multifides se palpent :","o":["À 2-3 cm en dedans de l'EIAS","Latéralement au rachis, vers la vertèbre inférieure","Sur la ligne médiane, sur les épineuses","Au niveau du sacrum uniquement, de chaque côté"],"r":1,"e":"Les obliques interne et externe se palpent, eux, à 2 à 3 cm en dedans de l'épine iliaque antéro-supérieure.","s":5},{"q":"Parmi les stabilisateurs locaux palpés figurent :","o":["Le diaphragme, le transverse, les multifides et le plancher pelvien","Les obliques interne et externe, et le grand droit de l'abdomen","Le grand droit et le carré des lombes","Le carré des lombes et les érecteurs du rachis"],"r":0,"e":"Les obliques appartiennent aux stabilisateurs globaux, dont la contraction se distingue nettement de celle des locaux.","s":5},{"q":"Une saillie de l'abdomen pendant les tests traduit :","o":["Une bonne activation","Une stabilité insuffisante","Une hypertonie du transverse","Un excès de contraction"],"r":1,"e":"Rotation du bassin, inclinaison latérale, saillie de la cage thoracique et altération du schéma respiratoire signalent, eux, une faiblesse du transverse ou du plancher pelvien.","s":5},{"q":"À l'inspiration, la grille costale doit :","o":["Se relâcher","S'ouvrir latéralement","Rester immobile","Se fermer"],"r":1,"e":"À l'expiration, elle se relâche. Le schéma respiratoire est à identifier : costal supérieur, costal inférieur ou abdomino-diaphragmatique.","s":5},{"q":"Parmi les repères posturaux de l'évaluation lombaire, le cours cite :","o":["Le lobe de l'oreille derrière la clavicule","Le lobe de l'oreille devant la clavicule","L'alignement des scapulas avec les EIPS","Le grand trochanter aligné avec la rotule"],"r":0,"e":"S'y ajoutent l'alignement symétrique clavicule-scapula, le bassin neutre sans rotation sacrée, le grand trochanter aligné avec la malléole externe et le talus avec le calcanéus.","s":5},{"q":"Les tests de contrôle dynamique en décubitus ventral comprennent :","o":["La flexion du genou et l'extension de la hanche","Le SLR actif et la flexion de hanche","L'appui unipodal et la flexion du tronc","Le squat bipodal et l'extension du genou en charge, pieds écartés"],"r":0,"e":"Le SLR actif se réalise en décubitus dorsal ; l'appui unipodal et le squat font partie des tests debout, avec l'analyse du pas.","s":5},{"q":"Les tests de contrôle dynamique en quatre pattes comprennent :","o":["L'alignement, la flexion de hanche bilatérale, l'extension unilatérale","Le squat, l'appui unipodal et l'analyse du pas pendant la marche","Le SLR actif, jambe tendue, puis jambe fléchie","La manœuvre de Valsalva, en apnée et poussée"],"r":0,"e":"Cette position réduit la contrainte gravitaire tout en exigeant un contrôle actif du tronc, ce qui en fait une étape intermédiaire utile.","s":5},{"q":"Le test de proprioception lombo-pelvienne cité a été développé par :","o":["Panjabi et collaborateurs, en 1992","Maffey-Ward et collaborateurs, en 1996","Bergmark et collaborateurs, en 1989","O'Sullivan et collaborateurs, en 2000"],"r":1,"e":"Le kinésithérapeute place passivement la zone en position neutre, demande au patient de bouger, puis lui demande de la retrouver activement.","s":5},{"q":"Au test de proprioception, la cotation « moyen » correspond à un patient qui :","o":["Retrouve la position neutre avec confiance","Retrouve la position, mais se montre incertain","Ne parvient pas à retrouver la position neutre","Refuse le test, par peur de la douleur"],"r":1,"e":"« Bon » correspond à une récupération assurée, « faible » à un échec. L'incertitude est un signe en soi, indépendamment du résultat.","s":5},{"q":"La mesure de la longueur des membres inférieurs se réalise :","o":["Debout, au mètre ruban, de l'EIAS jusqu'au sol, pieds joints","En décubitus dorsal, du nombril puis de l'EIAS à la malléole","Assis, de l'EIAS jusqu'au bord supérieur de la rotule","En procubitus, de l'EIPS jusqu'à la pointe du talon"],"r":1,"e":"La double mesure permet de distinguer une différence réelle, retrouvée à partir de l'EIAS, d'une différence fonctionnelle liée à une bascule du bassin. La malléole utilisée est la malléole interne.","s":5},{"q":"Dans l'examen subjectif lombaire, le SIN désigne :","o":["Sévérité, irritabilité et nature de la douleur","Siège, intensité et nature de la douleur","Sévérité, intensité et névralgie","Signes, imagerie et nature exacte de la douleur"],"r":0,"e":"Ces trois paramètres conditionnent la conduite de l'examen objectif : une douleur très irritable impose de limiter les tests provocateurs.","s":5},{"q":"La démarche du raisonnement clinique en évaluation lombaire suit l'ordre :","o":["Traiter, tester, poser l'hypothèse, réévaluer","Développer des hypothèses, tester, traiter, réévaluer","Réévaluer, traiter, tester, puis poser l'hypothèse","Tester, traiter, conclure, puis développer des hypothèses"],"r":1,"e":"L'examen subjectif fournit la matière des hypothèses ; l'examen objectif les met à l'épreuve avant toute décision thérapeutique.","s":5},{"q":"Que traduisent des lignes scapulaire et pelvienne croisées ?","o":["Une chaîne ascendante","Une chaîne descendante","Un équilibre parfait","Une chaîne statique"],"r":0,"e":"Des lignes parallèles signent une chaîne descendante.","s":6},{"q":"Quelle chaîne est influencée par le pied ?","o":["La chaîne podale","La chaîne sacrée","La chaîne statique","La chaîne viscérale"],"r":0,"e":"C'est une chaîne dynamique ; la chaîne sacrée est influencée par le bassin.","s":6},{"q":"Quels muscles sont inhibés dans la chaîne podale ?","o":["Tibial postérieur, fibulaires, tibial antérieur et soléaire","Psoas, droit fémoral, piriforme et carré des lombes","Carré des lombes, grand fessier, ischio-jambiers et paravertébraux","Ischio-jambiers, paravertébraux et grand fessier"],"r":0,"e":"Les muscles cités en second relèvent de la chaîne sacrée.","s":6},{"q":"À quoi la chaîne sacrée est-elle associée ?","o":["À une chaîne statique, influencée par la chaîne viscérale","À une chaîne dynamique, influencée par le pied et le sol","À la chaîne d'ouverture, influencée par le membre inférieur","À aucune autre chaîne, car elle est indépendante"],"r":0,"e":"Elle est influencée par le bassin.","s":6},{"q":"Comment se présente l'EIPS dans un iliaque en antériorité ?","o":["Haute","Basse","Inchangée","Latéralisée"],"r":0,"e":"L'EIAS et la crête iliaque sont basses.","s":6},{"q":"Quelle posture accompagne l'iliaque en antériorité ?","o":["Une hyperlordose lombaire","Une rectitude lombaire","Une cyphose thoracique","Une scoliose"],"r":0,"e":"Il en résulte une antéversion du bassin, avec recurvatum de genou.","s":6},{"q":"Quels muscles sont impliqués dans l'iliaque en antériorité ?","o":["Le carré des lombes et le droit fémoral","Le droit de l'abdomen et les ischio-jambiers","Les fessiers et le périnée","Le transverse et les adducteurs"],"r":0,"e":"Le carré des lombes monte la partie postérieure de l'aile iliaque, le droit fémoral descend la partie antérieure.","s":6},{"q":"Quels muscles sont impliqués dans l'iliaque en postériorité ?","o":["Le droit de l'abdomen et les ischio-jambiers","Le carré des lombes et le droit fémoral","Les fessiers et le périnée","Le transverse et les adducteurs"],"r":0,"e":"Il en résulte une rétroversion du bassin et une rectitude lombaire.","s":6},{"q":"Comment se comporte le sacrum dans un iliaque en postériorité ?","o":["Il se verticalise et devient plus bas","Il s'horizontalise et devient plus haut","Il ne bouge pas, quelle que soit la position","Il tourne latéralement, vers le côté atteint"],"r":0,"e":"En antériorité, le sacrum est horizontalisé et plus haut.","s":6},{"q":"Quel signe au genou accompagne l'iliaque en postériorité ?","o":["Un flexum de genou","Un recurvatum de genou","Un varum","Un valgum"],"r":0,"e":"On note aussi des douleurs localisées dans la région des ischions.","s":6},{"q":"Quel muscle travaille-t-on dans le traitement de l'iliaque antérieur ?","o":["Le grand fessier, par allongement du membre contre résistance","Le quadriceps, par extension du genou contre résistance","Les adducteurs, par serrage des genoux contre résistance","Le transverse, par rentrée du ventre contre résistance"],"r":0,"e":"Au relâchement, on augmente la postériorité ; on répète 3 fois.","s":6},{"q":"Quels muscles interviennent dans l'iliaque en ouverture ?","o":["Les fessiers et le périnée","Le transverse de l'abdomen et les adducteurs","Le carré des lombes et le droit fémoral","Les ischio-jambiers"],"r":0,"e":"Les fessiers tractent la partie supérieure vers l'extérieur, le périnée la partie inférieure vers le dedans.","s":6},{"q":"Quel signe distingue l'iliaque en ouverture ?","o":["Distance nombril–EIAS augmentée et genu varum","Distance nombril–EIAS diminuée et genu valgum","EIPS basse et EIAS haute du même côté","Rectitude lombaire et flexum de genou"],"r":0,"e":"En fermeture, la distance diminue et le genou est en valgum.","s":6},{"q":"Quels muscles interviennent dans l'iliaque en fermeture ?","o":["Le transverse de l'abdomen et les adducteurs","Les fessiers et le périnée","Le droit de l'abdomen et les ischio-jambiers","Le carré des lombes"],"r":0,"e":"EIAS, crête et EIPS sont toutes basses, avec valgum de genou.","s":6},{"q":"Comment se réalise le test d'ouverture de l'iliaque ?","o":["DD, flexion, adduction, rotation externe : le membre s'allonge","DD, flexion, abduction, rotation interne : le membre s'allonge","Debout, en appui unipodal : le bassin chute du côté non appuyé","DV, extension de hanche : le membre se raccourcit au fur et à mesure"],"r":0,"e":"Le test de fermeture combine flexion, abduction et rotation interne ; le membre doit se raccourcir. DD : décubitus dorsal ; DV : décubitus ventral.","s":6},{"q":"De quoi est composé le sling oblique postérieur ?","o":["Grand dorsal, fascia thoraco-lombaire, grand fessier et biceps fémoral","Multifides, fessiers, rotateurs externes, bandelette ilio-tibiale","Oblique externe, grand dentelé, petit pectoral, transverse, oblique interne","Carré des lombes, moyen et petit fessier, TFL, adducteurs"],"r":0,"e":"Il permet le squat et favorise l'efficience de l'extension et le contrôle lombo-pelvien. Grand fessier et biceps fémoral sont controlatéraux, avec le ligament sacro-tubéral.","s":6},{"q":"Quel geste permet le sling longitudinal ?","o":["Le saut","Le squat","Le lancer","L'appui unipodal"],"r":0,"e":"Il favorise le renforcement de la chaîne d'extension, la stabilité SI et le contrôle de la flexion latérale.","s":6},{"q":"Quel geste permet le sling oblique antérieur ?","o":["Le lancer","Le squat","Le saut","La marche arrière"],"r":0,"e":"Il favorise la relation thorax/hanche, la stabilité pelvienne et le contrôle rotationnel.","s":6},{"q":"De quoi est composé le sling latéral ?","o":["Carré des lombes, moyen et petit fessier, TFL, adducteur","Grand dorsal, grand fessier controlatéral, biceps fémoral, TFL","Multifides, fibulaires, long fibulaire et bandelette ilio-tibiale","Grand dentelé, petit pectoral, oblique externe, transverse"],"r":0,"e":"Il assure l'équilibre en appui unipodal et l'alignement hanche-genou. Le carré des lombes et l'adducteur sont controlatéraux ; le TFL agit avec la bandelette ilio-tibiale.","s":6},{"q":"Quel test évalue les slings ?","o":["Le SLR actif","Le test de Schober","Le signe de Trendelenburg","Le test de FABER"],"r":0,"e":"Il évalue la capacité de transfert de charge, les compensations et la stabilité pelvienne.","s":6},{"q":"Quel est l'objectif du traitement face à un recrutement dysfonctionnel ?","o":["Une reprogrammation sensori-motrice, en inversant la séquence de recrutement","Un renforcement analytique maximal de chaque muscle","Une immobilisation, le temps que la douleur passe","Un étirement passif prolongé, en fin d'amplitude, maintenu au moins deux minutes"],"r":0,"e":"On progresse par postures statiques, postures dynamiques puis intégration fonctionnelle.","s":6},{"q":"Quelle consigne respiratoire est absolue en stabilité lombaire ?","o":["Ne jamais utiliser l'apnée","Toujours travailler en apnée","Respirer uniquement par la bouche","Bloquer l'expiration"],"r":0,"e":"Fermer les yeux améliore la conscience du mouvement de la grille costale.","s":6},{"q":"Combien de répétitions lentes commence-t-on par demander ?","o":["5 à 7, dans l'amplitude de contrôle actif","20 à 30, d'emblée, à vitesse rapide et en charge","1 à 2, en contraction maximale","50, en série continue, sans pause"],"r":0,"e":"On atteint progressivement les 20-30 répétitions.","s":6},{"q":"Comment évolue le feedback au cours du réapprentissage moteur ?","o":["Beaucoup de feedback externe, puis interne, puis plus du tout","Aucun feedback dès le début, puis feedback externe croissant","Feedback externe croissant tout au long de l'apprentissage","Feedback visuel seul, au miroir, du début à la fin"],"r":0,"e":"L'objectif initial est d'augmenter la conscience du mouvement.","s":6},{"q":"Quel exemple illustre le travail du système global ?","o":["Le one leg circle","Lever une jambe","Lever les membres supérieurs","Maintenir l'alignement couché"],"r":0,"e":"Le système local se travaille dans des tâches d'exigence simple.","s":6},{"q":"Quel est l'ordre des composantes de la séance ?","o":["Échauffement, stabilité statique, dynamique, rotatoire, mobilité, relaxation","Mobilité, échauffement, stabilité statique et dynamique, étirements, relaxation","Étirements, stabilité rotatoire, échauffement, mobilité, relaxation","Stabilité rotatoire, statique, dynamique, échauffement, étirements"],"r":0,"e":"L'association de tâches augmente ensuite la charge et intègre des surfaces instables. Les étirements accompagnent la relaxation finale.","s":6},{"q":"Que désigne l'entérotome ?","o":["Les dysfonctions neurovégétatives viscérales","La douleur cutanée réflexe","La douleur sur le périoste et les ligaments","La congestion vasculaire locale"],"r":0,"e":"L'angiotome correspond à la congestion locale au niveau vasculaire.","s":6},{"q":"Comment se caractérise la douleur viscérale ?","o":["Vague, profonde et diffuse","Bien localisée, superficielle et vive","Bien localisée, profonde et mécanique","Nocturne, isolée et pulsatile"],"r":0,"e":"La douleur pariétale est bien localisée et profonde.","s":6},{"q":"Où se situe le trigger point du cardia ?","o":["2 doigts sous l'appendice xiphoïde et 2 doigts à sa gauche","3 doigts latéralement à gauche du nombril, en oblique","À mi-distance entre le nombril et la 10ᵉ côte droite, sous le gril","Entre le nombril et l'EIAS droite"],"r":0,"e":"Il relie l'œsophage et l'estomac ; le pylore se situe 3 doigts latéralement en oblique à gauche du nombril.","s":6},{"q":"Pourquoi une atteinte du foie donne-t-elle une douleur à l'épaule droite ?","o":["Par le nerf phrénique droit, issu de C3-C4","Par le nerf vague, issu du tronc cérébral et du bulbe","Par le plexus sacré, issu de L4-S3","Par le nerf axillaire, issu de C5-C6"],"r":0,"e":"Le muscle associé est le trapèze supérieur, la vertèbre T8/T9.","s":6},{"q":"Une chaîne est dite ascendante lorsque les lignes entre ceinture scapulaire et bassin sont :","o":["Parallèles","Croisées","Verticales","Absentes"],"r":1,"e":"Des lignes parallèles signent au contraire une chaîne descendante. Le déséquilibre d'une extrémité implique toujours celui de l'autre.","s":6},{"q":"La chaîne podale est influencée par :","o":["Le bassin","Le pied","Le rachis cervical","Le diaphragme"],"r":1,"e":"Ses muscles inhibés sont le tibial postérieur, les fibulaires, le tibial antérieur et le soléaire. La chaîne sacrée est, elle, influencée par le bassin.","s":6},{"q":"Parmi les muscles inhibés de la chaîne sacrée, le cours cite :","o":["Le tibial postérieur, les fibulaires et le soléaire","Le psoas, le droit fémoral, le piriforme, le carré des lombes","Le deltoïde, le trapèze et le grand dorsal","Le grand dorsal, le grand dentelé, le petit pectoral et le subclavier"],"r":1,"e":"Elle est associée à une chaîne statique avec influence de la chaîne viscérale, ce qui explique son lien avec le diaphragme. S'y ajoutent le grand fessier, les ischio-jambiers et les paravertébraux.","s":6},{"q":"Dans une iliaque en antériorité, l'EIPS est :","o":["Basse","Haute","Alignée","Absente"],"r":1,"e":"L'EIAS et la crête iliaque sont basses. En postériorité, tout s'inverse : EIAS haute, EIPS basse.","s":6},{"q":"L'iliaque en antériorité s'accompagne au membre inférieur :","o":["D'un flexum de genou et de douleurs ischiatiques","D'altérations fémoro-patellaires et d'un recurvatum de genou","D'un genu varum et d'une supination du pied, avec un appui externe","D'aucune conséquence au membre inférieur"],"r":1,"e":"En postériorité, on observe au contraire un flexum de genou et des douleurs dans la région des ischions.","s":6},{"q":"Dans l'iliaque en antériorité, les muscles en cause sont :","o":["Le droit de l'abdomen qui monte l'avant et les ischio-jambiers qui descendent l'arrière","Le carré des lombes qui monte l'arrière, le droit fémoral qui descend l'avant","Le grand fessier seul, qui bascule l'aile iliaque vers l'arrière","Le psoas seul, qui tire l'aile iliaque vers l'avant"],"r":1,"e":"En postériorité, ce sont le droit de l'abdomen qui monte la partie antérieure et les ischio-jambiers qui descendent la partie postérieure. Il s'agit de l'aile iliaque.","s":6},{"q":"Le sacrum, dans une iliaque en antériorité, est :","o":["Verticalisé et plus bas","Horizontalisé et plus haut","Inchangé","Latéralisé"],"r":1,"e":"En postériorité, il est verticalisé et plus bas, avec une rectitude lombaire et une compression accrue des disques intervertébraux.","s":6},{"q":"Une iliaque en ouverture se traduit par :","o":["Une distance nombril-EIAS diminuée et un genu valgum","Une distance nombril-EIAS augmentée et un genu varum","Une hyperlordose et une antériorité de l'iliaque","Un flexum de genou et une postériorité"],"r":1,"e":"La fermeture produit l'inverse : diminution de cette distance et genu valgum.","s":6},{"q":"Le sling oblique postérieur est sollicité principalement lors :","o":["Du squat","Du saut","Du lancer","De l'appui unipodal"],"r":0,"e":"Le sling longitudinal intervient au saut, l'oblique antérieur au lancer, le latéral à l'appui unipodal.","s":6},{"q":"Le sling latéral est sollicité lors :","o":["Du squat bipodal","Du saut vertical","Du lancer du bras","De l'appui unipodal"],"r":3,"e":"Chacun des quatre slings correspond à un geste fonctionnel type, ce qui permet de choisir l'exercice en fonction du système à travailler.","s":6},{"q":"Le réapprentissage moteur débute par :","o":["20 à 30 répétitions rapides","5 à 7 répétitions lentes, dans l'amplitude contrôlée","Une contraction maximale unique","Des exercices en charge, avec poids et haltères libres"],"r":1,"e":"On progresse ensuite jusqu'à 20 ou 30 répétitions. La règle absolue : ne jamais utiliser l'apnée.","s":6},{"q":"Le plan de séance en stabilité lombaire suit l'ordre :","o":["Échauffement, stabilité statique, dynamique et rotatoire, mobilité, relaxation","Étirements, renforcement analytique, mobilité, puis stabilité dynamique","Mobilité, force maximale, endurance, puis échauffement de fin de séance","Échauffement, force maximale, récupération active, puis étirements passifs"],"r":0,"e":"La progression va du plus contrôlé au plus exigeant, puis se referme par la mobilité et la relaxation.","s":6},{"q":"Dans le traitement d'une iliaque antérieure gauche, le kinésithérapeute se place :","o":["Du même côté que la lésion, à gauche","Du côté opposé à la lésion, à droite","À la tête du patient, face à lui","Aux pieds du patient, dans l'axe de la table de traitement"],"r":1,"e":"Il imprime une rotation du bassin pour qu'il soit perpendiculaire à la table, place le pied gauche du patient sur son EIAS gauche et sa main droite sur la sacro-iliaque gauche.","s":6},{"q":"Dans cette technique, le patient doit :","o":["Fléchir librement le membre inférieur, sans résistance du kiné","Allonger le membre contre la résistance du kiné","Retenir sa respiration, pendant la poussée","Rester passif, le kiné faisant tout"],"r":1,"e":"Le relâchement qui suit la contraction permet de gagner la correction recherchée, selon le principe du contracter-relâcher. Cela fait travailler le grand fessier.","s":6},{"q":"Les chaînes décrivent, selon le cours, la façon dont le corps :","o":["Produit sa force maximale, en recrutant tous les muscles d'une chaîne","Transmet les forces, compense les tensions et garde son équilibre","Récupère après l'effort, par le relâchement des chaînes","Se développe pendant la croissance, de la naissance à l'âge adulte"],"r":1,"e":"La désorganisation d'un segment avec rétractions musculaires et fasciales implique une posture compensatoire, comme l'ont montré Azato et ses collaborateurs en 2013. Il s'organise pour maintenir l'équilibre et la verticalité.","s":6},{"q":"Lors du positionnement pour le traitement de l'iliaque, hanche, genou et pied du patient doivent être :","o":["Dans des plans différents","Dans le même plan","En rotation externe","En abduction maximale"],"r":1,"e":"Cet alignement garantit que la force appliquée agisse bien sur l'articulation visée, sans se dissiper dans les articulations intermédiaires.","s":6},{"q":"Dans une iliaque en antériorité, le pubis et l'ischion se déplacent ainsi :","o":["Montée du pubis, descente de l'ischion","Descente du pubis, montée de l'ischion","Les deux montent","Les deux descendent"],"r":1,"e":"En postériorité, le mouvement s'inverse : montée du pubis et descente de l'ischion, cohérentes avec la rétroversion du bassin.","s":6},{"q":"Le sling oblique antérieur est sollicité lors :","o":["Du squat","Du saut","Du lancer","De la marche lente"],"r":2,"e":"Il relie l'oblique externe d'un côté à l'adducteur controlatéral, par l'intermédiaire du fascia abdominal antérieur.","s":6},{"q":"L'iliaque en postériorité s'accompagne au rachis :","o":["D'une hyperlordose lombaire et d'un iliaque en antériorité","D'une rectitude lombaire, avec compression accrue des disques","D'une scoliose lombaire, avec rotation des vertèbres et gibbosité","D'une cyphose thoracique, avec antépulsion de la tête"],"r":1,"e":"L'antériorité produit au contraire une hyperlordose lombaire. Ces deux dysfonctions donnent donc des tableaux rachidiens opposés.","s":6},{"q":"La règle respiratoire du réapprentissage moteur en stabilité lombaire est :","o":["De bloquer la respiration pendant l'effort","De ne jamais utiliser l'apnée","De respirer le plus vite possible","D'expirer uniquement"],"r":1,"e":"L'apnée augmente la pression intra-abdominale de façon non contrôlée et court-circuite précisément le travail de coordination recherché.","s":6}]};
